#[derive(Clone)]
struct LineInfo {
    raw: String,
    content: String, // after indent, comment stripped, right-trimmed
    indent: usize,   // number of leading whitespace chars
    byte_start: usize, // byte offset in src of raw line start
    significant: bool,
}

fn strip_comment(s: &str) -> &str {
    let mut in_s = false;
    let mut in_d = false;
    let mut prev: Option<char> = None;
    let mut chars = s.char_indices().peekable();
    while let Some((i, ch)) = chars.next() {
        if in_d {
            if ch == '\\' { let _ = chars.next(); prev = Some(ch); continue; }
            if ch == '"' { in_d = false; }
        } else if in_s {
            if ch == '\'' {
                if let Some((_, '\'')) = chars.peek() { let _ = chars.next(); } else { in_s = false; }
            }
        } else {
            match ch {
                '"' => in_d = true,
                '\'' => in_s = true,
                '#' => {
                    if i == 0 || matches!(prev, Some(' ') | Some('\t')) {
                        return &s[..i];
                    }
                }
                _ => {}
            }
        }
        prev = Some(ch);
    }
    s
}

fn make_line(raw: &str, byte_start: usize) -> LineInfo {
    let no_comment = strip_comment(raw);
    let trimmed_right = no_comment.trim_end();
    let mut indent = 0usize;
    for ch in trimmed_right.chars() {
        if ch == ' ' || ch == '\t' { indent += 1; } else { break; }
    }
    // content starts after indent bytes: indent chars are ascii spaces/tabs, byte == count
    let content = if indent <= trimmed_right.len() { trimmed_right[indent..].to_string() } else { String::new() };
    let significant = !content.trim().is_empty();
    LineInfo { raw: raw.to_string(), content, indent, byte_start, significant }
}

fn classify_plain(raw: &str) -> Yaml {
    let s = raw.trim();
    if s.is_empty() || s == "null" || s == "~" {
        return Yaml::Null;
    }
    if s == "true" { return Yaml::Bool(true); }
    if s == "false" { return Yaml::Bool(false); }
    if let Some(i) = parse_yaml_int(s) { return Yaml::Int(i); }
    if is_yaml_float(s) { return Yaml::Real(s.to_string()); }
    Yaml::Str(s.to_string())
}

fn parse_yaml_int(s: &str) -> Option<i64> {
    let mut t = s;
    let mut sign = 1i64;
    if let Some(rest) = t.strip_prefix('-') { sign = -1; t = rest; }
    else if let Some(rest) = t.strip_prefix('+') { t = rest; }
    if t.is_empty() { return None; }
    if let Some(hex) = t.strip_prefix("0x").or_else(|| t.strip_prefix("0X")) {
        if !hex.is_empty() && hex.chars().all(|c| c.is_ascii_hexdigit() || c == '_') {
            return i64::from_str_radix(&hex.replace('_', ""), 16).ok().map(|v| sign * v);
        }
        return None;
    }
    if let Some(oct) = t.strip_prefix("0o").or_else(|| t.strip_prefix("0O")) {
        if !oct.is_empty() && oct.chars().all(|c| ('0'..='7').contains(&c) || c == '_') {
            return i64::from_str_radix(&oct.replace('_', ""), 8).ok().map(|v| sign * v);
        }
        return None;
    }
    if t.chars().all(|c| c.is_ascii_digit() || c == '_') && t.chars().any(|c| c.is_ascii_digit()) {
        // Reject underscores at ends? Approximation is sufficient for typing.
        return t.replace('_', "").parse::<i64>().ok().map(|v| sign * v);
    }
    None
}

fn is_yaml_float(s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    if lower == ".inf" || lower == "+.inf" || lower == "-.inf" || lower == ".nan" {
        return true;
    }
    // Must have digits and a dot or exponent, parseable as f64, only allowed chars.
    if !s.chars().all(|c| c.is_ascii_digit() || matches!(c, '.' | 'e' | 'E' | '+' | '-' | '_')) { return false; }
    if !s.chars().any(|c| c.is_ascii_digit()) { return false; }
    if !(s.contains('.') || s.contains('e') || s.contains('E')) { return false; }
    s.replace('_', "").parse::<f64>().is_ok()
}

fn find_mapping_colon(content: &str) -> Option<usize> {
    let mut in_s = false;
    let mut in_d = false;
    let mut depth = 0i32;
    let bytes: Vec<(usize, char)> = content.char_indices().collect();
    let mut idx = 0usize;
    while idx < bytes.len() {
        let (i, ch) = bytes[idx];
        if in_d {
            if ch == '\\' { idx += 2; continue; }
            if ch == '"' { in_d = false; }
        } else if in_s {
            if ch == '\'' { in_s = false; }
        } else {
            match ch {
                '"' => in_d = true,
                '\'' => in_s = true,
                '{' | '[' => depth += 1,
                '}' | ']' => depth -= 1,
                ':' if depth == 0 => {
                    // Colon must be followed by space/tab/end
                    let next = bytes.get(idx + 1).map(|b| b.1);
                    if next.is_none() || matches!(next, Some(' ') | Some('\t')) {
                        return Some(i);
                    }
                }
                _ => {}
            }
        }
        idx += 1;
    }
    None
}

fn is_flow_incomplete(s: &str) -> bool {
    let mut in_s = false;
    let mut in_d = false;
    let mut depth = 0i32;
    let mut chars = s.chars().peekable();
    while let Some(ch) = chars.next() {
        if in_d {
            if ch == '\\' { let _ = chars.next(); continue; }
            if ch == '"' { in_d = false; }
        } else if in_s {
            if ch == '\'' {
                if chars.peek() == Some(&'\'') { let _ = chars.next(); } else { in_s = false; }
            }
        } else {
            match ch {
                '"' => in_d = true,
                '\'' => in_s = true,
                '{' | '[' => depth += 1,
                '}' | ']' => depth -= 1,
                _ => {}
            }
        }
    }
    in_s || in_d || depth > 0
}

struct InlineParser<'a> {
    src: &'a str,           // original full source, for errors
    text: Vec<char>,
    byte_offsets: Vec<usize>, // per char byte offset in local text string
    pos: usize,
    base: usize, // byte offset in src of local text start
    local_len_bytes: usize,
    anchors: &'a mut HashMap<String, Yaml>,
}

impl<'a> InlineParser<'a> {
    fn new(src: &'a str, text: &str, base: usize, anchors: &'a mut HashMap<String, Yaml>) -> Self {
        let mut tc = Vec::new();
        let mut offs = Vec::new();
        for (i, ch) in text.char_indices() { tc.push(ch); offs.push(i); }
        InlineParser { src, text: tc, byte_offsets: offs, pos: 0, base, local_len_bytes: text.len(), anchors }
    }
    fn err(&self, local_char_pos: usize, info: &str) -> ScanError {
        let byte = if local_char_pos < self.byte_offsets.len() {
            self.base + self.byte_offsets[local_char_pos]
        } else {
            self.base + self.local_len_bytes
        };
        ScanError::new(self.src, byte, info)
    }
    fn peek(&self) -> Option<char> { self.text.get(self.pos).copied() }
    fn bump(&mut self) -> Option<char> { let c = self.peek(); if c.is_some() { self.pos += 1; } c }
    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(' ') | Some('\t') | Some('\n') | Some('\r')) { self.pos += 1; }
    }
    fn parse_node(&mut self, flow: bool) -> Result<Yaml, ScanError> {
        self.skip_ws();
        let start = self.pos;
        // prefixes
        let mut anchor_names: Vec<String> = Vec::new();
        let mut tag: Option<String> = None;
        loop {
            self.skip_ws();
            match self.peek() {
                Some('&') => {
                    self.bump();
                    let name = self.parse_name_token();
                    anchor_names.push(name);
                }
                Some('!') => {
                    self.bump();
                    if self.peek() == Some('<') {
                        self.bump();
                        let mut t = String::new();
                        while let Some(c) = self.bump() {
                            if c == '>' { break; }
                            t.push(c);
                        }
                        tag = Some(t);
                    } else {
                        let mut t = String::from("!");
                        // tag may be !!str or !foo
                        while let Some(c) = self.peek() {
                            if c.is_whitespace() || c == ',' || c == ']' || c == '}' { break; }
                            t.push(c); self.bump();
                        }
                        tag = Some(t);
                    }
                }
                Some('*') => {
                    let alias_start = self.pos;
                    self.bump();
                    let name = self.parse_name_token();
                    if let Some(v) = self.anchors.get(&name).cloned() {
                        return Ok(v);
                    } else {
                        return Err(self.err(alias_start, "while parsing node, found unknown anchor"));
                    }
                }
                _ => break,
            }
        }
        self.skip_ws();
        if self.peek().is_none() {
            return Err(self.err(self.pos, "while parsing a node, did not find expected node content"));
        }
        let node_start = self.pos;
        let mut node = match self.peek().unwrap() {
            '{' => self.parse_flow_map()?,
            '[' => self.parse_flow_seq()?,
            '"' => Yaml::Str(self.parse_double_quoted(node_start)?),
            '\'' => Yaml::Str(self.parse_single_quoted(node_start)?),
            _ => {
                let raw = self.parse_plain(flow);
                if tag.as_deref() == Some("!!str") || tag.as_deref() == Some("!") && false {
                    Yaml::Str(raw)
                } else if tag.as_deref() == Some("!!int") {
                    if let Some(i) = parse_yaml_int(raw.trim()) { Yaml::Int(i) } else { Yaml::Int(0) }
                } else if tag.as_deref() == Some("!!float") {
                    Yaml::Real(raw.trim().to_string())
                } else if tag.as_deref() == Some("!!bool") {
                    Yaml::Bool(raw.trim() == "true")
                } else if tag.as_deref() == Some("!!null") {
                    Yaml::Null
                } else {
                    classify_plain(&raw)
                }
            }
        };
        if tag.as_deref() == Some("!!str") {
            if let Yaml::Str(_) = node {} else {
                // Convert scalar text representation approximations
                node = Yaml::Str(match &node {
                    Yaml::Int(i) => i.to_string(),
                    Yaml::Bool(b) => b.to_string(),
                    Yaml::Real(s) => s.clone(),
                    _ => String::new(),
                });
            }
        }
        for name in anchor_names {
            self.anchors.insert(name, node.clone());
        }
        let _ = start;
        Ok(node)
    }
    fn parse_name_token(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_whitespace() || c == ',' || c == ']' || c == '}' || c == '{' || c == '[' { break; }
            s.push(c); self.bump();
        }
        s
    }
    fn parse_plain(&mut self, flow: bool) -> String {
        let mut s = String::new();
        if !flow {
            while let Some(c) = self.bump() { s.push(c); }
            return s.trim().to_string();
        }
        while let Some(c) = self.peek() {
            if c == ',' || c == ']' || c == '}' { break; }
            if c == ':' {
                // stop if colon likely key separator or flow terminator
                let nxt = self.text.get(self.pos + 1).copied();
                if nxt.is_none() || matches!(nxt, Some(' ') | Some('\t') | Some(',') | Some('}') | Some(']') | Some('\n')) {
                    break;
                }
            }
            if c == ':' && false { break; }
            s.push(c); self.bump();
        }
        s.trim().to_string()
    }
    fn parse_double_quoted(&mut self, start: usize) -> Result<String, ScanError> {
        // consume opening
        self.bump();
        let mut out = String::new();
        loop {
            match self.bump() {
                None => return Err(self.err(start, "while scanning a quoted scalar, found unexpected end of stream")),
                Some('"') => break,
                Some('\\') => {
                    match self.bump() {
                        None => return Err(self.err(start, "while scanning a quoted scalar, found unexpected end of stream")),
                        Some('n') => out.push('\n'),
                        Some('t') => out.push('\t'),
                        Some('r') => out.push('\r'),
                        Some('0') => out.push('\0'),
                        Some('\\') => out.push('\\'),
                        Some('"') => out.push('"'),
                        Some('\'') => out.push('\''),
                        Some('/') => out.push('/'),
                        Some('b') => out.push('\u{0008}'),
                        Some('f') => out.push('\u{000c}'),
                        Some('x') => {
                            let h = self.take_hex(2);
                            if let Some(v) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) { out.push(v); }
                        }
                        Some('u') => {
                            let h = self.take_hex(4);
                            if let Some(v) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) { out.push(v); }
                        }
                        Some('U') => {
                            let h = self.take_hex(8);
                            if let Some(v) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) { out.push(v); }
                        }
                        Some('\n') => {
                            // line continuation: skip following whitespace
                            self.skip_ws();
                        }
                        Some(c) => { out.push(c); }
                    }
                }
                Some(c) => out.push(c),
            }
        }
        Ok(out)
    }
    fn take_hex(&mut self, n: usize) -> String {
        let mut s = String::new();
        for _ in 0..n {
            if let Some(c) = self.bump() { s.push(c); } else { break; }
        }
        s
    }
    fn parse_single_quoted(&mut self, start: usize) -> Result<String, ScanError> {
        self.bump();
        let mut out = String::new();
        loop {
            match self.bump() {
                None => return Err(self.err(start, "while scanning a quoted scalar, found unexpected end of stream")),
                Some('\'') => {
                    if self.peek() == Some('\'') { self.bump(); out.push('\''); } else { break; }
                }
                Some(c) => out.push(c),
            }
        }
        Ok(out)
    }
    fn parse_flow_seq(&mut self) -> Result<Yaml, ScanError> {
        self.bump(); // [
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') { self.bump(); return Ok(Yaml::Array(items)); }
        loop {
            self.skip_ws();
            if self.peek().is_none() {
                return Err(self.err(self.pos, "while parsing a node, did not find expected node content"));
            }
            let item = self.parse_node(true)?;
            items.push(item);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.bump(); self.skip_ws(); if self.peek() == Some(']') { self.bump(); break; } }
                Some(']') => { self.bump(); break; }
                _ => {
                    return Err(self.err(self.pos, "while parsing a flow sequence, expected ',' or ']'"));
                }
            }
        }
        Ok(Yaml::Array(items))
    }
    fn parse_flow_map(&mut self) -> Result<Yaml, ScanError> {
        self.bump(); // {
        let mut entries: Vec<(Yaml, Yaml)> = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') { self.bump(); return Ok(Yaml::Hash(entries)); }
        loop {
            self.skip_ws();
            if self.peek().is_none() {
                return Err(self.err(self.pos, "while parsing a node, did not find expected node content"));
            }
            // key
            let key = self.parse_node(true)?;
            self.skip_ws();
            let value = if self.peek() == Some(':') {
                self.bump(); self.skip_ws();
                if matches!(self.peek(), Some(',') | Some('}') | None) {
                    if self.peek().is_none() {
                        return Err(self.err(self.pos, "while parsing a node, did not find expected node content"));
                    }
                    Yaml::Null
                } else {
                    self.parse_node(true)?
                }
            } else {
                Yaml::Null
            };
            insert_hash(&mut entries, key, value);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.bump(); self.skip_ws(); if self.peek() == Some('}') { self.bump(); break; } }
                Some('}') => { self.bump(); break; }
                _ => {
                    return Err(self.err(self.pos, "while parsing a flow mapping, expected ',' or '}'"));
                }
            }
        }
        Ok(Yaml::Hash(entries))
    }
    fn parse_complete(&mut self, flow: bool) -> Result<Yaml, ScanError> {
        let v = self.parse_node(flow)?;
        self.skip_ws();
        Ok(v)
    }
}

struct BlockParser<'a> {
    src: &'a str,
    lines: Vec<LineInfo>,
    pos: usize,
    anchors: HashMap<String, Yaml>,
}

impl<'a> BlockParser<'a> {
    fn peek_sig_index(&self) -> Option<usize> {
        let mut i = self.pos;
        while i < self.lines.len() {
            if self.lines[i].significant { return Some(i); }
            i += 1;
        }
        None
    }
    fn skip_insig(&mut self) {
        if let Some(i) = self.peek_sig_index() { self.pos = i; } else { self.pos = self.lines.len(); }
    }
    fn parse_document(&mut self) -> Result<Yaml, ScanError> {
        self.skip_insig();
        if self.pos >= self.lines.len() { return Ok(Yaml::Null); }
        let indent = self.lines[self.pos].indent;
        self.parse_node_block(indent)
    }
    fn parse_node_block(&mut self, min_indent: usize) -> Result<Yaml, ScanError> {
        self.skip_insig();
        if self.pos >= self.lines.len() { return Ok(Yaml::Null); }
        let line = self.lines[self.pos].clone();
        if line.indent < min_indent { return Ok(Yaml::Null); }
        let content = line.content.clone();
        // Sequence
        if content == "-" || content.starts_with("- ") || content.starts_with("-\t") {
            return self.parse_sequence(line.indent);
        }
        // Flow / quoted at start: not a mapping (unless quoted key)
        let first = content.chars().next().unwrap_or(' ');
        if first == '{' || first == '[' {
            self.pos += 1;
            let base = line.byte_start + line.indent;
            let text = self.collect_flow_text(content);
            let mut ip = InlineParser::new(self.src, &text, base, &mut self.anchors);
            return ip.parse_complete(true);
        }
        if find_mapping_colon(&content).is_some() {
            return self.parse_mapping(line.indent);
        }
        // Scalar / block scalar / anchor-tag only
        self.pos += 1;
        let base = line.byte_start + line.indent;
        // Block scalar at top/scalar context
        if is_block_scalar_header(&content) {
            return Ok(Yaml::Str(self.parse_block_scalar(&content, line.indent)));
        }
        // If content is only anchor/tag tokens, parse nested
        if is_only_prefixes(&content) {
            // collect prefix parse using inline on empty? Simplify: parse nested block then register anchor if present
            let nested = if let Some(idx) = self.peek_sig_index() {
                if self.lines[idx].indent > line.indent {
                    let ind = self.lines[idx].indent;
                    self.parse_node_block(ind)?
                } else { Yaml::Null }
            } else { Yaml::Null };
            // Apply anchor names in content
            for tok in content.split_whitespace() {
                if let Some(name) = tok.strip_prefix('&') {
                    self.anchors.insert(name.to_string(), nested.clone());
                }
            }
            return Ok(nested);
        }
        let text = self.collect_flow_text(content);
        let mut ip = InlineParser::new(self.src, &text, base, &mut self.anchors);
        ip.parse_complete(false)
    }
    fn collect_flow_text(&mut self, mut text: String) -> String {
        while is_flow_incomplete(&text) {
            if self.pos >= self.lines.len() { break; }
            let nxt = self.lines[self.pos].clone();
            self.pos += 1;
            text.push('\n');
            text.push_str(&" ".repeat(nxt.indent));
            text.push_str(&nxt.content);
            // note: raw line ignoring comment stripping complications is acceptable
        }
        text
    }
    fn parse_mapping(&mut self, indent: usize) -> Result<Yaml, ScanError> {
        let mut entries: Vec<(Yaml, Yaml)> = Vec::new();
        loop {
            self.skip_insig();
            if self.pos >= self.lines.len() { break; }
            let line = self.lines[self.pos].clone();
            if line.indent != indent { break; }
            let colon = match find_mapping_colon(&line.content) {
                Some(c) => c,
                None => break,
            };
            let key_str = line.content[..colon].trim();
            let key_base = line.byte_start + line.indent;
            let key = {
                let mut ip = InlineParser::new(self.src, key_str, key_base, &mut self.anchors);
                if key_str.is_empty() { Yaml::Null } else { ip.parse_complete(true)? }
            };
            let rest_raw = &line.content[colon + 1..];
            let rest = rest_raw.trim_start().to_string();
            let rest_offset = line.content.len() - rest.len();
            let rest_base = line.byte_start + line.indent + rest_offset;
            self.pos += 1; // consume line
            let value = if rest.is_empty() {
                // nested block or null; sequence may be at same indent
                if let Some(idx) = self.peek_sig_index() {
                    let nline = self.lines[idx].clone();
                    if nline.indent > indent {
                        self.parse_node_block(nline.indent)?
                    } else if nline.indent == indent && (nline.content == "-" || nline.content.starts_with("- ") || nline.content.starts_with("-\t")) {
                        self.parse_sequence(indent)?
                    } else {
                        Yaml::Null
                    }
                } else {
                    Yaml::Null
                }
            } else if is_block_scalar_header(&rest) {
                Yaml::Str(self.parse_block_scalar(&rest, indent))
            } else if is_only_prefixes(&rest) {
                let nested = if let Some(idx) = self.peek_sig_index() {
                    if self.lines[idx].indent > indent {
                        let ind = self.lines[idx].indent;
                        self.parse_node_block(ind)?
                    } else { Yaml::Null }
                } else { Yaml::Null };
                for tok in rest.split_whitespace() {
                    if let Some(name) = tok.strip_prefix('&') {
                        self.anchors.insert(name.to_string(), nested.clone());
                    }
                }
                nested
            } else {
                let text = self.collect_flow_text(rest);
                let mut ip = InlineParser::new(self.src, &text, rest_base, &mut self.anchors);
                ip.parse_complete(false)?
            };
            insert_hash(&mut entries, key, value);
        }
        Ok(Yaml::Hash(entries))
    }
    fn parse_sequence(&mut self, indent: usize) -> Result<Yaml, ScanError> {
        let mut items = Vec::new();
        loop {
            self.skip_insig();
            if self.pos >= self.lines.len() { break; }
            let line = self.lines[self.pos].clone();
            if line.indent != indent { break; }
            if !(line.content == "-" || line.content.starts_with("- ") || line.content.starts_with("-\t")) { break; }
            // Rest after dash
            let after_dash = if line.content.len() > 1 { &line.content[1..] } else { "" };
            let rest = after_dash.trim_start().to_string();
            let rest_col = line.indent + (line.content.len() - rest.len());
            self.pos += 1;
            if rest.is_empty() {
                let v = if let Some(idx) = self.peek_sig_index() {
                    if self.lines[idx].indent > indent {
                        let ind = self.lines[idx].indent;
                        self.parse_node_block(ind)?
                    } else { Yaml::Null }
                } else { Yaml::Null };
                items.push(v);
            } else {
                // Insert a synthetic line for rest at rest_col
                let synth = LineInfo {
                    raw: format!("{}{}", " ".repeat(rest_col), rest.clone()),
                    content: rest.clone(),
                    indent: rest_col,
                    byte_start: line.byte_start + (line.content.len() - rest.len()),
                    significant: true,
                };
                self.lines.insert(self.pos, synth);
                let v = self.parse_node_block(rest_col)?;
                items.push(v);
            }
        }
        Ok(Yaml::Array(items))
    }
    fn parse_block_scalar(&mut self, header: &str, parent_indent: usize) -> String {
        let folded = header.trim_start().starts_with('>');
        let mut chomp_strip = false;
        let mut explicit_indent: Option<usize> = None;
        for ch in header.chars().skip(1) {
            match ch {
                '-' => chomp_strip = true,
                '+' => {},
                '1'..='9' => explicit_indent = Some(parent_indent + (ch as usize - '0' as usize)),
                ' ' | '\t' => break,
                _ => {}
            }
        }
        let mut collected: Vec<String> = Vec::new();
        let mut content_indent: Option<usize> = explicit_indent;
        while self.pos < self.lines.len() {
            let line = self.lines[self.pos].clone();
            if line.significant && line.indent <= parent_indent { break; }
            self.pos += 1;
            if !line.significant {
                collected.push(String::new());
                continue;
            }
            if content_indent.is_none() { content_indent = Some(line.indent); }
            let ci = content_indent.unwrap_or(line.indent);
            // Reconstruct from raw without comment stripping for block scalars:
            // Use line.raw (original) removing ci leading ws chars if possible.
            let raw = line.raw.trim_end();
            let mut stripped = String::new();
            let mut removed = 0usize;
            for ch in raw.chars() {
                if removed < ci && (ch == ' ' || ch == '\t') { removed += 1; continue; }
                stripped.push(ch);
            }
            collected.push(stripped);
        }
        // Remove trailing blank lines collected beyond? Keep for '+' approximations:
        // Strip trailing empty lines for clip/strip default handling below.
        while matches!(collected.last(), Some(s) if s.is_empty()) {
            // For default clip, one trailing newline is due to final joining; pop all then re-add logic
            collected.pop();
        }
        if collected.is_empty() { return String::new(); }
        let mut result = if folded {
            let mut s = String::new();
            let mut prev_nonempty = false;
            for l in &collected {
                if l.is_empty() {
                    s.push('\n');
                    prev_nonempty = false;
                } else {
                    if prev_nonempty { s.push(' '); }
                    s.push_str(l);
                    prev_nonempty = true;
                }
            }
            s
        } else {
            collected.join("\n")
        };
        if !chomp_strip {
            result.push('\n');
        }
        result
    }
}

fn is_block_scalar_header(s: &str) -> bool {
    let t = s.trim_start();
    if !(t.starts_with('|') || t.starts_with('>')) { return false; }
    let rest = &t[1..];
    // header may contain +,-,digit and then space/comment/end
    let mut chars = rest.chars();
    let mut saw_any_indicator_char = false;
    while let Some(c) = chars.next() {
        match c {
            '+' | '-' | '0'..='9' => saw_any_indicator_char = true,
            ' ' | '\t' => break,
            _ => return false,
        }
        let _ = saw_any_indicator_char;
    }
    true
}
fn is_only_prefixes(s: &str) -> bool {
    let toks: Vec<&str> = s.split_whitespace().collect();
    if toks.is_empty() { return false; }
    toks.iter().all(|t| t.starts_with('&') || t.starts_with('!'))
}

pub fn load_from_str(src: &str) -> Result<Vec<Yaml>, ScanError> {
    // Build lines with byte offsets
    let mut physical: Vec<LineInfo> = Vec::new();
    let mut offset = 0usize;
    // Rust lines handling: split preserving offsets; src may not end with newline
    for part in src.split('\n') {
        let raw = part.strip_suffix('\r').unwrap_or(part);
        physical.push(make_line(raw, offset));
        offset += part.len() + 1;
    }
    // If src ends with \n, split gives a trailing empty part; it's insignificant and harmless.
    // Documents grouping
    struct DocSeg { lines: Vec<LineInfo>, explicit: bool }
    let mut docs: Vec<DocSeg> = Vec::new();
    let mut cur: Vec<LineInfo> = Vec::new();
    let mut cur_explicit = false;
    let mut started = false; // have we started a doc (explicit or content)
    let mut between_docs = false;
    for line in physical {
        let is_marker = line.indent == 0 && (line.content == "---" || line.content.starts_with("--- ") || line.content.starts_with("---\t"));
        let is_end = line.indent == 0 && (line.content == "..." || line.content.starts_with("... ") || line.content.starts_with("...\t"));
        if is_marker {
            if started || cur_explicit || cur.iter().any(|l| l.significant) {
                docs.push(DocSeg { lines: std::mem::take(&mut cur), explicit: cur_explicit });
            }
            cur_explicit = true;
            started = true;
            between_docs = false;
            // content after ---
            let after = line.content[3..].trim_start().to_string();
            if !after.is_empty() {
                let synth = LineInfo { raw: after.clone(), content: after.clone(), indent: 0, byte_start: line.byte_start + 3, significant: true };
                cur.push(synth);
            }
            continue;
        }
        if is_end {
            if !started && !cur_explicit && !cur.iter().any(|l| l.significant) {
                return Err(ScanError::new(src, line.byte_start, "while parsing a node, did not find expected node content"));
            }
            docs.push(DocSeg { lines: std::mem::take(&mut cur), explicit: cur_explicit });
            cur_explicit = false;
            started = false;
            between_docs = true;
            continue;
        }
        if line.significant {
            started = true;
            between_docs = false;
        }
        // In between_docs, insignificant lines are ignored until next doc; but pushing them harmless.
        let _ = between_docs;
        cur.push(line);
    }
    if cur_explicit || cur.iter().any(|l| l.significant) {
        docs.push(DocSeg { lines: cur, explicit: cur_explicit });
    }
    if docs.is_empty() {
        return Ok(Vec::new());
    }
    let mut out = Vec::new();
    for doc in docs {
        let mut parser = BlockParser { src, lines: doc.lines, pos: 0, anchors: HashMap::new() };
        let v = parser.parse_document()?;
        out.push(v);
    }
    Ok(out)
}
RS_EOF
"}

actions.command:
cat > src/yaml.rs <<'RS_EOF'
use std::collections::HashMap;

#[derive(Clone, PartialEq)]
pub enum Yaml {
    Null,
    Bool(bool),
    Int(i64),
    Real(String),
    Str(String),
    Array(Vec<Yaml>),
    Hash(Vec<(Yaml, Yaml)>),
}

impl std::fmt::Debug for Yaml {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Yaml::Null => write!(f, "Null"),
            Yaml::Bool(b) => write!(f, "Boolean({:?})", b),
            Yaml::Int(i) => write!(f, "Integer({:?})", i),
            Yaml::Real(s) => write!(f, "Real({:?})", s),
            Yaml::Str(s) => write!(f, "String({:?})", s),
            Yaml::Array(a) => write!(f, "Array({:?})", a),
            Yaml::Hash(h) => write!(f, "Hash({:?})", h),
        }
    }
}

impl Yaml {
    pub fn as_str(&self) -> Option<&str> {
        if let Yaml::Str(s) = self { Some(s) } else { None }
    }
    pub fn as_hash(&self) -> Option<&Vec<(Yaml, Yaml)>> {
        if let Yaml::Hash(h) = self { Some(h) } else { None }
    }
    pub fn lookup<'a>(&'a self, key: &str) -> Option<&'a Yaml> {
        if let Yaml::Hash(h) = self {
            for (k, v) in h {
                if let Yaml::Str(s) = k {
                    if s == key { return Some(v); }
                }
            }
        }
        None
    }
}

pub fn lookup<'a>(y: Option<&'a Yaml>, key: &str) -> Option<&'a Yaml> {
    y.and_then(|v| v.lookup(key))
}

pub fn insert_hash(h: &mut Vec<(Yaml, Yaml)>, k: Yaml, v: Yaml) {
    for pair in h.iter_mut() {
        if pair.0 == k { pair.1 = v; return; }
    }
    h.push((k, v));
}

#[derive(Clone)]
pub struct Marker { pub index: usize, pub line: usize, pub col: usize }
impl std::fmt::Debug for Marker {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Marker {{ index: {}, line: {}, col: {} }}", self.index, self.line, self.col)
    }
}

#[derive(Clone)]
pub struct ScanError { pub mark: Marker, pub info: String }
impl std::fmt::Debug for ScanError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ScanError {{ mark: {:?}, info: {:?} }}", self.mark, self.info)
    }
}
impl ScanError {
    fn new(src: &str, byte_index: usize, info: &str) -> Self {
        let mut line = 1usize;
        let mut col = 0usize;
        for (i, ch) in src.char_indices() {
            if i >= byte_index { break; }
            if ch == '\n' { line += 1; col = 0; } else { col += 1; }
        }
        if byte_index >= src.len() && !src.is_empty() {
            line = 1; col = 0;
            for ch in src.chars() {
                if ch == '\n' { line += 1; col = 0; } else { col += 1; }
            }
        }
        ScanError { mark: Marker { index: byte_index, line, col }, info: info.to_string() }
    }
}

#[derive(Clone)]
struct LineInfo {
    raw: String,
    content: String, // after indent, comment stripped, right-trimmed
    indent: usize,   // number of leading whitespace chars
    byte_start: usize, // byte offset in src of raw line start
    significant: bool,
}

fn strip_comment(s: &str) -> &str {
    let mut in_s = false;
    let mut in_d = false;
    let mut prev: Option<char> = None;
    let mut chars = s.char_indices().peekable();
    while let Some((i, ch)) = chars.next() {
        if in_d {
            if ch == '\\' { let _ = chars.next(); prev = Some(ch); continue; }
            if ch == '"' { in_d = false; }
        } else if in_s {
            if ch == '\'' {
                if let Some((_, '\'')) = chars.peek() { let _ = chars.next(); } else { in_s = false; }
            }
        } else {
            match ch {
                '"' => in_d = true,
                '\'' => in_s = true,
                '#' => {
                    if i == 0 || matches!(prev, Some(' ') | Some('\t')) {
                        return &s[..i];
                    }
                }
                _ => {}
            }
        }
        prev = Some(ch);
    }
    s
}

fn make_line(raw: &str, byte_start: usize) -> LineInfo {
    let no_comment = strip_comment(raw);
    let trimmed_right = no_comment.trim_end();
    let mut indent = 0usize;
    for ch in trimmed_right.chars() {
        if ch == ' ' || ch == '\t' { indent += 1; } else { break; }
    }
    // content starts after indent bytes: indent chars are ascii spaces/tabs, byte == count
    let content = if indent <= trimmed_right.len() { trimmed_right[indent..].to_string() } else { String::new() };
    let significant = !content.trim().is_empty();
    LineInfo { raw: raw.to_string(), content, indent, byte_start, significant }
}

fn classify_plain(raw: &str) -> Yaml {
    let s = raw.trim();
    if s.is_empty() || s == "null" || s == "~" {
        return Yaml::Null;
    }
    if s == "true" { return Yaml::Bool(true); }
    if s == "false" { return Yaml::Bool(false); }
    if let Some(i) = parse_yaml_int(s) { return Yaml::Int(i); }
    if is_yaml_float(s) { return Yaml::Real(s.to_string()); }
    Yaml::Str(s.to_string())
}

fn parse_yaml_int(s: &str) -> Option<i64> {
    let mut t = s;
    let mut sign = 1i64;
    if let Some(rest) = t.strip_prefix('-') { sign = -1; t = rest; }
    else if let Some(rest) = t.strip_prefix('+') { t = rest; }
    if t.is_empty() { return None; }
    if let Some(hex) = t.strip_prefix("0x").or_else(|| t.strip_prefix("0X")) {
        if !hex.is_empty() && hex.chars().all(|c| c.is_ascii_hexdigit() || c == '_') {
            return i64::from_str_radix(&hex.replace('_', ""), 16).ok().map(|v| sign * v);
        }
        return None;
    }
    if let Some(oct) = t.strip_prefix("0o").or_else(|| t.strip_prefix("0O")) {
        if !oct.is_empty() && oct.chars().all(|c| ('0'..='7').contains(&c) || c == '_') {
            return i64::from_str_radix(&oct.replace('_', ""), 8).ok().map(|v| sign * v);
        }
        return None;
    }
    if t.chars().all(|c| c.is_ascii_digit() || c == '_') && t.chars().any(|c| c.is_ascii_digit()) {
        // Reject underscores at ends? Approximation is sufficient for typing.
        return t.replace('_', "").parse::<i64>().ok().map(|v| sign * v);
    }
    None
}

fn is_yaml_float(s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    if lower == ".inf" || lower == "+.inf" || lower == "-.inf" || lower == ".nan" {
        return true;
    }
    // Must have digits and a dot or exponent, parseable as f64, only allowed chars.
    if !s.chars().all(|c| c.is_ascii_digit() || matches!(c, '.' | 'e' | 'E' | '+' | '-' | '_')) { return false; }
    if !s.chars().any(|c| c.is_ascii_digit()) { return false; }
    if !(s.contains('.') || s.contains('e') || s.contains('E')) { return false; }
    s.replace('_', "").parse::<f64>().is_ok()
}

fn find_mapping_colon(content: &str) -> Option<usize> {
    let mut in_s = false;
    let mut in_d = false;
    let mut depth = 0i32;
    let bytes: Vec<(usize, char)> = content.char_indices().collect();
    let mut idx = 0usize;
    while idx < bytes.len() {
        let (i, ch) = bytes[idx];
        if in_d {
            if ch == '\\' { idx += 2; continue; }
            if ch == '"' { in_d = false; }
        } else if in_s {
            if ch == '\'' { in_s = false; }
        } else {
            match ch {
                '"' => in_d = true,
                '\'' => in_s = true,
                '{' | '[' => depth += 1,
                '}' | ']' => depth -= 1,
                ':' if depth == 0 => {
                    // Colon must be followed by space/tab/end
                    let next = bytes.get(idx + 1).map(|b| b.1);
                    if next.is_none() || matches!(next, Some(' ') | Some('\t')) {
                        return Some(i);
                    }
                }
                _ => {}
            }
        }
        idx += 1;
    }
    None
}

fn is_flow_incomplete(s: &str) -> bool {
    let mut in_s = false;
    let mut in_d = false;
    let mut depth = 0i32;
    let mut chars = s.chars().peekable();
    while let Some(ch) = chars.next() {
        if in_d {
            if ch == '\\' { let _ = chars.next(); continue; }
            if ch == '"' { in_d = false; }
        } else if in_s {
            if ch == '\'' {
                if chars.peek() == Some(&'\'') { let _ = chars.next(); } else { in_s = false; }
            }
        } else {
            match ch {
                '"' => in_d = true,
                '\'' => in_s = true,
                '{' | '[' => depth += 1,
                '}' | ']' => depth -= 1,
                _ => {}
            }
        }
    }
    in_s || in_d || depth > 0
}

struct InlineParser<'a> {
    src: &'a str,           // original full source, for errors
    text: Vec<char>,
    byte_offsets: Vec<usize>, // per char byte offset in local text string
    pos: usize,
    base: usize, // byte offset in src of local text start
    local_len_bytes: usize,
    anchors: &'a mut HashMap<String, Yaml>,
}

impl<'a> InlineParser<'a> {
    fn new(src: &'a str, text: &str, base: usize, anchors: &'a mut HashMap<String, Yaml>) -> Self {
        let mut tc = Vec::new();
        let mut offs = Vec::new();
        for (i, ch) in text.char_indices() { tc.push(ch); offs.push(i); }
        InlineParser { src, text: tc, byte_offsets: offs, pos: 0, base, local_len_bytes: text.len(), anchors }
    }
    fn err(&self, local_char_pos: usize, info: &str) -> ScanError {
        let byte = if local_char_pos < self.byte_offsets.len() {
            self.base + self.byte_offsets[local_char_pos]
        } else {
            self.base + self.local_len_bytes
        };
        ScanError::new(self.src, byte, info)
    }
    fn peek(&self) -> Option<char> { self.text.get(self.pos).copied() }
    fn bump(&mut self) -> Option<char> { let c = self.peek(); if c.is_some() { self.pos += 1; } c }
    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(' ') | Some('\t') | Some('\n') | Some('\r')) { self.pos += 1; }
    }
    fn parse_node(&mut self, flow: bool) -> Result<Yaml, ScanError> {
        self.skip_ws();
        let start = self.pos;
        // prefixes
        let mut anchor_names: Vec<String> = Vec::new();
        let mut tag: Option<String> = None;
        loop {
            self.skip_ws();
            match self.peek() {
                Some('&') => {
                    self.bump();
                    let name = self.parse_name_token();
                    anchor_names.push(name);
                }
                Some('!') => {
                    self.bump();
                    if self.peek() == Some('<') {
                        self.bump();
                        let mut t = String::new();
                        while let Some(c) = self.bump() {
                            if c == '>' { break; }
                            t.push(c);
                        }
                        tag = Some(t);
                    } else {
                        let mut t = String::from("!");
                        // tag may be !!str or !foo
                        while let Some(c) = self.peek() {
                            if c.is_whitespace() || c == ',' || c == ']' || c == '}' { break; }
                            t.push(c); self.bump();
                        }
                        tag = Some(t);
                    }
                }
                Some('*') => {
                    let alias_start = self.pos;
                    self.bump();
                    let name = self.parse_name_token();
                    if let Some(v) = self.anchors.get(&name).cloned() {
                        return Ok(v);
                    } else {
                        return Err(self.err(alias_start, "while parsing node, found unknown anchor"));
                    }
                }
                _ => break,
            }
        }
        self.skip_ws();
        if self.peek().is_none() {
            return Err(self.err(self.pos, "while parsing a node, did not find expected node content"));
        }
        let node_start = self.pos;
        let mut node = match self.peek().unwrap() {
            '{' => self.parse_flow_map()?,
            '[' => self.parse_flow_seq()?,
            '"' => Yaml::Str(self.parse_double_quoted(node_start)?),
            '\'' => Yaml::Str(self.parse_single_quoted(node_start)?),
            _ => {
                let raw = self.parse_plain(flow);
                if tag.as_deref() == Some("!!str") || tag.as_deref() == Some("!") && false {
                    Yaml::Str(raw)
                } else if tag.as_deref() == Some("!!int") {
                    if let Some(i) = parse_yaml_int(raw.trim()) { Yaml::Int(i) } else { Yaml::Int(0) }
                } else if tag.as_deref() == Some("!!float") {
                    Yaml::Real(raw.trim().to_string())
                } else if tag.as_deref() == Some("!!bool") {
                    Yaml::Bool(raw.trim() == "true")
                } else if tag.as_deref() == Some("!!null") {
                    Yaml::Null
                } else {
                    classify_plain(&raw)
                }
            }
        };
        if tag.as_deref() == Some("!!str") {
            if let Yaml::Str(_) = node {} else {
                // Convert scalar text representation approximations
                node = Yaml::Str(match &node {
                    Yaml::Int(i) => i.to_string(),
                    Yaml::Bool(b) => b.to_string(),
                    Yaml::Real(s) => s.clone(),
                    _ => String::new(),
                });
            }
        }
        for name in anchor_names {
            self.anchors.insert(name, node.clone());
        }
        let _ = start;
        Ok(node)
    }
    fn parse_name_token(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_whitespace() || c == ',' || c == ']' || c == '}' || c == '{' || c == '[' { break; }
            s.push(c); self.bump();
        }
        s
    }
    fn parse_plain(&mut self, flow: bool) -> String {
        let mut s = String::new();
        if !flow {
            while let Some(c) = self.bump() { s.push(c); }
            return s.trim().to_string();
        }
        while let Some(c) = self.peek() {
            if c == ',' || c == ']' || c == '}' { break; }
            if c == ':' {
                // stop if colon likely key separator or flow terminator
                let nxt = self.text.get(self.pos + 1).copied();
                if nxt.is_none() || matches!(nxt, Some(' ') | Some('\t') | Some(',') | Some('}') | Some(']') | Some('\n')) {
                    break;
                }
            }
            if c == ':' && false { break; }
            s.push(c); self.bump();
        }
        s.trim().to_string()
    }
    fn parse_double_quoted(&mut self, start: usize) -> Result<String, ScanError> {
        // consume opening
        self.bump();
        let mut out = String::new();
        loop {
            match self.bump() {
                None => return Err(self.err(start, "while scanning a quoted scalar, found unexpected end of stream")),
                Some('"') => break,
                Some('\\') => {
                    match self.bump() {
                        None => return Err(self.err(start, "while scanning a quoted scalar, found unexpected end of stream")),
                        Some('n') => out.push('\n'),
                        Some('t') => out.push('\t'),
                        Some('r') => out.push('\r'),
                        Some('0') => out.push('\0'),
                        Some('\\') => out.push('\\'),
                        Some('"') => out.push('"'),
                        Some('\'') => out.push('\''),
                        Some('/') => out.push('/'),
                        Some('b') => out.push('\u{0008}'),
                        Some('f') => out.push('\u{000c}'),
                        Some('x') => {
                            let h = self.take_hex(2);
                            if let Some(v) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) { out.push(v); }
                        }
                        Some('u') => {
                            let h = self.take_hex(4);
                            if let Some(v) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) { out.push(v); }
                        }
                        Some('U') => {
                            let h = self.take_hex(8);
                            if let Some(v) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) { out.push(v); }
                        }
                        Some('\n') => {
                            // line continuation: skip following whitespace
                            self.skip_ws();
                        }
                        Some(c) => { out.push(c); }
                    }
                }
                Some(c) => out.push(c),
            }
        }
        Ok(out)
    }
    fn take_hex(&mut self, n: usize) -> String {
        let mut s = String::new();
        for _ in 0..n {
            if let Some(c) = self.bump() { s.push(c); } else { break; }
        }
        s
    }
    fn parse_single_quoted(&mut self, start: usize) -> Result<String, ScanError> {
        self.bump();
        let mut out = String::new();
        loop {
            match self.bump() {
                None => return Err(self.err(start, "while scanning a quoted scalar, found unexpected end of stream")),
                Some('\'') => {
                    if self.peek() == Some('\'') { self.bump(); out.push('\''); } else { break; }
                }
                Some(c) => out.push(c),
            }
        }
        Ok(out)
    }
    fn parse_flow_seq(&mut self) -> Result<Yaml, ScanError> {
        self.bump(); // [
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') { self.bump(); return Ok(Yaml::Array(items)); }
        loop {
            self.skip_ws();
            if self.peek().is_none() {
                return Err(self.err(self.pos, "while parsing a node, did not find expected node content"));
            }
            let item = self.parse_node(true)?;
            items.push(item);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.bump(); self.skip_ws(); if self.peek() == Some(']') { self.bump(); break; } }
                Some(']') => { self.bump(); break; }
                _ => {
                    return Err(self.err(self.pos, "while parsing a flow sequence, expected ',' or ']'"));
                }
            }
        }
        Ok(Yaml::Array(items))
    }
    fn parse_flow_map(&mut self) -> Result<Yaml, ScanError> {
        self.bump(); // {
        let mut entries: Vec<(Yaml, Yaml)> = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') { self.bump(); return Ok(Yaml::Hash(entries)); }
        loop {
            self.skip_ws();
            if self.peek().is_none() {
                return Err(self.err(self.pos, "while parsing a node, did not find expected node content"));
            }
            // key
            let key = self.parse_node(true)?;
            self.skip_ws();
            let value = if self.peek() == Some(':') {
                self.bump(); self.skip_ws();
                if matches!(self.peek(), Some(',') | Some('}') | None) {
                    if self.peek().is_none() {
                        return Err(self.err(self.pos, "while parsing a node, did not find expected node content"));
                    }
                    Yaml::Null
                } else {
                    self.parse_node(true)?
                }
            } else {
                Yaml::Null
            };
            insert_hash(&mut entries, key, value);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.bump(); self.skip_ws(); if self.peek() == Some('}') { self.bump(); break; } }
                Some('}') => { self.bump(); break; }
                _ => {
                    return Err(self.err(self.pos, "while parsing a flow mapping, expected ',' or '}'"));
                }
            }
        }
        Ok(Yaml::Hash(entries))
    }
    fn parse_complete(&mut self, flow: bool) -> Result<Yaml, ScanError> {
        let v = self.parse_node(flow)?;
        self.skip_ws();
        Ok(v)
    }
}

struct BlockParser<'a> {
    src: &'a str,
    lines: Vec<LineInfo>,
    pos: usize,
    anchors: HashMap<String, Yaml>,
}

impl<'a> BlockParser<'a> {
    fn peek_sig_index(&self) -> Option<usize> {
        let mut i = self.pos;
        while i < self.lines.len() {
            if self.lines[i].significant { return Some(i); }
            i += 1;
        }
        None
    }
    fn skip_insig(&mut self) {
        if let Some(i) = self.peek_sig_index() { self.pos = i; } else { self.pos = self.lines.len(); }
    }
    fn parse_document(&mut self) -> Result<Yaml, ScanError> {
        self.skip_insig();
        if self.pos >= self.lines.len() { return Ok(Yaml::Null); }
        let indent = self.lines[self.pos].indent;
        self.parse_node_block(indent)
    }
    fn parse_node_block(&mut self, min_indent: usize) -> Result<Yaml, ScanError> {
        self.skip_insig();
        if self.pos >= self.lines.len() { return Ok(Yaml::Null); }
        let line = self.lines[self.pos].clone();
        if line.indent < min_indent { return Ok(Yaml::Null); }
        let content = line.content.clone();
        // Sequence
        if content == "-" || content.starts_with("- ") || content.starts_with("-\t") {
            return self.parse_sequence(line.indent);
        }
        // Flow / quoted at start: not a mapping (unless quoted key)
        let first = content.chars().next().unwrap_or(' ');
        if first == '{' || first == '[' {
            self.pos += 1;
            let base = line.byte_start + line.indent;
            let text = self.collect_flow_text(content);
            let mut ip = InlineParser::new(self.src, &text, base, &mut self.anchors);
            return ip.parse_complete(true);
        }
        if find_mapping_colon(&content).is_some() {
            return self.parse_mapping(line.indent);
        }
        // Scalar / block scalar / anchor-tag only
        self.pos += 1;
        let base = line.byte_start + line.indent;
        // Block scalar at top/scalar context
        if is_block_scalar_header(&content) {
            return Ok(Yaml::Str(self.parse_block_scalar(&content, line.indent)));
        }
        // If content is only anchor/tag tokens, parse nested
        if is_only_prefixes(&content) {
            // collect prefix parse using inline on empty? Simplify: parse nested block then register anchor if present
            let nested = if let Some(idx) = self.peek_sig_index() {
                if self.lines[idx].indent > line.indent {
                    let ind = self.lines[idx].indent;
                    self.parse_node_block(ind)?
                } else { Yaml::Null }
            } else { Yaml::Null };
            // Apply anchor names in content
            for tok in content.split_whitespace() {
                if let Some(name) = tok.strip_prefix('&') {
                    self.anchors.insert(name.to_string(), nested.clone());
                }
            }
            return Ok(nested);
        }
        let text = self.collect_flow_text(content);
        let mut ip = InlineParser::new(self.src, &text, base, &mut self.anchors);
        ip.parse_complete(false)
    }
    fn collect_flow_text(&mut self, mut text: String) -> String {
        while is_flow_incomplete(&text) {
            if self.pos >= self.lines.len() { break; }
            let nxt = self.lines[self.pos].clone();
            self.pos += 1;
            text.push('\n');
            text.push_str(&" ".repeat(nxt.indent));
            text.push_str(&nxt.content);
            // note: raw line ignoring comment stripping complications is acceptable
        }
        text
    }
    fn parse_mapping(&mut self, indent: usize) -> Result<Yaml, ScanError> {
        let mut entries: Vec<(Yaml, Yaml)> = Vec::new();
        loop {
            self.skip_insig();
            if self.pos >= self.lines.len() { break; }
            let line = self.lines[self.pos].clone();
            if line.indent != indent { break; }
            let colon = match find_mapping_colon(&line.content) {
                Some(c) => c,
                None => break,
            };
            let key_str = line.content[..colon].trim();
            let key_base = line.byte_start + line.indent;
            let key = {
                let mut ip = InlineParser::new(self.src, key_str, key_base, &mut self.anchors);
                if key_str.is_empty() { Yaml::Null } else { ip.parse_complete(true)? }
            };
            let rest_raw = &line.content[colon + 1..];
            let rest = rest_raw.trim_start().to_string();
            let rest_offset = line.content.len() - rest.len();
            let rest_base = line.byte_start + line.indent + rest_offset;
            self.pos += 1; // consume line
            let value = if rest.is_empty() {
                // nested block or null; sequence may be at same indent
                if let Some(idx) = self.peek_sig_index() {
                    let nline = self.lines[idx].clone();
                    if nline.indent > indent {
                        self.parse_node_block(nline.indent)?
                    } else if nline.indent == indent && (nline.content == "-" || nline.content.starts_with("- ") || nline.content.starts_with("-\t")) {
                        self.parse_sequence(indent)?
                    } else {
                        Yaml::Null
                    }
                } else {
                    Yaml::Null
                }
            } else if is_block_scalar_header(&rest) {
                Yaml::Str(self.parse_block_scalar(&rest, indent))
            } else if is_only_prefixes(&rest) {
                let nested = if let Some(idx) = self.peek_sig_index() {
                    if self.lines[idx].indent > indent {
                        let ind = self.lines[idx].indent;
                        self.parse_node_block(ind)?
                    } else { Yaml::Null }
                } else { Yaml::Null };
                for tok in rest.split_whitespace() {
                    if let Some(name) = tok.strip_prefix('&') {
                        self.anchors.insert(name.to_string(), nested.clone());
                    }
                }
                nested
            } else {
                let text = self.collect_flow_text(rest);
                let mut ip = InlineParser::new(self.src, &text, rest_base, &mut self.anchors);
                ip.parse_complete(false)?
            };
            insert_hash(&mut entries, key, value);
        }
        Ok(Yaml::Hash(entries))
    }
    fn parse_sequence(&mut self, indent: usize) -> Result<Yaml, ScanError> {
        let mut items = Vec::new();
        loop {
            self.skip_insig();
            if self.pos >= self.lines.len() { break; }
            let line = self.lines[self.pos].clone();
            if line.indent != indent { break; }
            if !(line.content == "-" || line.content.starts_with("- ") || line.content.starts_with("-\t")) { break; }
            // Rest after dash
            let after_dash = if line.content.len() > 1 { &line.content[1..] } else { "" };
            let rest = after_dash.trim_start().to_string();
            let rest_col = line.indent + (line.content.len() - rest.len());
            self.pos += 1;
            if rest.is_empty() {
                let v = if let Some(idx) = self.peek_sig_index() {
                    if self.lines[idx].indent > indent {
                        let ind = self.lines[idx].indent;
                        self.parse_node_block(ind)?
                    } else { Yaml::Null }
                } else { Yaml::Null };
                items.push(v);
            } else {
                // Insert a synthetic line for rest at rest_col
                let synth = LineInfo {
                    raw: format!("{}{}", " ".repeat(rest_col), rest.clone()),
                    content: rest.clone(),
                    indent: rest_col,
                    byte_start: line.byte_start + (line.content.len() - rest.len()),
                    significant: true,
                };
                self.lines.insert(self.pos, synth);
                let v = self.parse_node_block(rest_col)?;
                items.push(v);
            }
        }
        Ok(Yaml::Array(items))
    }
    fn parse_block_scalar(&mut self, header: &str, parent_indent: usize) -> String {
        let folded = header.trim_start().starts_with('>');
        let mut chomp_strip = false;
        let mut explicit_indent: Option<usize> = None;
        for ch in header.chars().skip(1) {
            match ch {
                '-' => chomp_strip = true,
                '+' => {},
                '1'..='9' => explicit_indent = Some(parent_indent + (ch as usize - '0' as usize)),
                ' ' | '\t' => break,
                _ => {}
            }
        }
        let mut collected: Vec<String> = Vec::new();
        let mut content_indent: Option<usize> = explicit_indent;
        while self.pos < self.lines.len() {
            let line = self.lines[self.pos].clone();
            if line.significant && line.indent <= parent_indent { break; }
            self.pos += 1;
            if !line.significant {
                collected.push(String::new());
                continue;
            }
            if content_indent.is_none() { content_indent = Some(line.indent); }
            let ci = content_indent.unwrap_or(line.indent);
            // Reconstruct from raw without comment stripping for block scalars:
            // Use line.raw (original) removing ci leading ws chars if possible.
            let raw = line.raw.trim_end();
            let mut stripped = String::new();
            let mut removed = 0usize;
            for ch in raw.chars() {
                if removed < ci && (ch == ' ' || ch == '\t') { removed += 1; continue; }
                stripped.push(ch);
            }
            collected.push(stripped);
        }
        // Remove trailing blank lines collected beyond? Keep for '+' approximations:
        // Strip trailing empty lines for clip/strip default handling below.
        while matches!(collected.last(), Some(s) if s.is_empty()) {
            // For default clip, one trailing newline is due to final joining; pop all then re-add logic
            collected.pop();
        }
        if collected.is_empty() { return String::new(); }
        let mut result = if folded {
            let mut s = String::new();
            let mut prev_nonempty = false;
            for l in &collected {
                if l.is_empty() {
                    s.push('\n');
                    prev_nonempty = false;
                } else {
                    if prev_nonempty { s.push(' '); }
                    s.push_str(l);
                    prev_nonempty = true;
                }
            }
            s
