}

fn is_block_scalar_header(s: &str) -> bool {
    let t = s.trim_start();
    if !(t.starts_with('|') || t.starts_with('>')) { return false; }
    let rest = &t[1..];
    // header may contain +,-,digit and then space/comment/end
    let mut chars = rest.chars();
    let mut saw_any_indicator_char = false;
    while let Some(c) = chars.next() {
        match c {
            '+' | '-' | '0'..='9' => saw_any_indicator_char = true,
            ' ' | '\t' => break,
            _ => return false,
        }
        let _ = saw_any_indicator_char;
    }
    true
}
fn is_only_prefixes(s: &str) -> bool {
    let toks: Vec<&str> = s.split_whitespace().collect();
    if toks.is_empty() { return false; }
    toks.iter().all(|t| t.starts_with('&') || t.starts_with('!'))
}

pub fn load_from_str(src: &str) -> Result<Vec<Yaml>, ScanError> {
    // Build lines with byte offsets
    let mut physical: Vec<LineInfo> = Vec::new();
    let mut offset = 0usize;
    // Rust lines handling: split preserving offsets; src may not end with newline
    for part in src.split('\n') {
        let raw = part.strip_suffix('\r').unwrap_or(part);
        physical.push(make_line(raw, offset));
        offset += part.len() + 1;
    }
    // If src ends with \n, split gives a trailing empty part; it's insignificant and harmless.
    // Documents grouping
    struct DocSeg { lines: Vec<LineInfo>, explicit: bool }
    let mut docs: Vec<DocSeg> = Vec::new();
    let mut cur: Vec<LineInfo> = Vec::new();
    let mut cur_explicit = false;
    let mut started = false; // have we started a doc (explicit or content)
    let mut between_docs = false;
    for line in physical {
        let is_marker = line.indent == 0 && (line.content == "---" || line.content.starts_with("--- ") || line.content.starts_with("---\t"));
        let is_end = line.indent == 0 && (line.content == "..." || line.content.starts_with("... ") || line.content.starts_with("...\t"));
        if is_marker {
            if started || cur_explicit || cur.iter().any(|l| l.significant) {
                docs.push(DocSeg { lines: std::mem::take(&mut cur), explicit: cur_explicit });
            }
            cur_explicit = true;
            started = true;
            between_docs = false;
            // content after ---
            let after = line.content[3..].trim_start().to_string();
            if !after.is_empty() {
                let synth = LineInfo { raw: after.clone(), content: after.clone(), indent: 0, byte_start: line.byte_start + 3, significant: true };
                cur.push(synth);
            }
            continue;
        }
        if is_end {
            if !started && !cur_explicit && !cur.iter().any(|l| l.significant) {
                return Err(ScanError::new(src, line.byte_start, "while parsing a node, did not find expected node content"));
            }
            docs.push(DocSeg { lines: std::mem::take(&mut cur), explicit: cur_explicit });
            cur_explicit = false;
            started = false;
            between_docs = true;
            continue;
        }
        if line.significant {
            started = true;
            between_docs = false;
        }
        // In between_docs, insignificant lines are ignored until next doc; but pushing them harmless.
        let _ = between_docs;
        cur.push(line);
    }
    if cur_explicit || cur.iter().any(|l| l.significant) {
        docs.push(DocSeg { lines: cur, explicit: cur_explicit });
    }
    if docs.is_empty() {
        return Ok(Vec::new());
    }
    let mut out = Vec::new();
    for doc in docs {
        let mut parser = BlockParser { src, lines: doc.lines, pos: 0, anchors: HashMap::new() };
        let v = parser.parse_document()?;
        out.push(v);
    }
    Ok(out)
}
