impl std::fmt::Debug for Yaml {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Yaml::Null => write!(f, "Null"),
            Yaml::Bool(b) => write!(f, "Boolean({:?})", b),
            Yaml::Int(i) => write!(f, "Integer({:?})", i),
            Yaml::Real(s) => write!(f, "Real({:?})", s),
            Yaml::Str(s) => write!(f, "String({:?})", s),
            Yaml::Array(a) => write!(f, "Array({:?})", a),
            Yaml::Hash(h) => write!(f, "Hash({:?})", h),
        }
    }
}

impl Yaml {
    pub fn as_str(&self) -> Option<&str> {
        if let Yaml::Str(s) = self { Some(s) } else { None }
    }
    pub fn as_hash(&self) -> Option<&Vec<(Yaml, Yaml)>> {
        if let Yaml::Hash(h) = self { Some(h) } else { None }
    }
    pub fn lookup<'a>(&'a self, key: &str) -> Option<&'a Yaml> {
        if let Yaml::Hash(h) = self {
            for (k, v) in h {
                if let Yaml::Str(s) = k {
                    if s == key { return Some(v); }
                }
            }
        }
        None
    }
}

pub fn lookup<'a>(y: Option<&'a Yaml>, key: &str) -> Option<&'a Yaml> {
    y.and_then(|v| v.lookup(key))
}

pub fn insert_hash(h: &mut Vec<(Yaml, Yaml)>, k: Yaml, v: Yaml) {
    for pair in h.iter_mut() {
        if pair.0 == k { pair.1 = v; return; }
    }
    h.push((k, v));
}

#[derive(Clone)]
pub struct Marker { pub index: usize, pub line: usize, pub col: usize }
impl std::fmt::Debug for Marker {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Marker {{ index: {}, line: {}, col: {} }}", self.index, self.line, self.col)
    }
}

#[derive(Clone)]
pub struct ScanError { pub mark: Marker, pub info: String }
impl std::fmt::Debug for ScanError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ScanError {{ mark: {:?}, info: {:?} }}", self.mark, self.info)
    }
}
impl ScanError {
    fn new(src: &str, byte_index: usize, info: &str) -> Self {
        let mut line = 1usize;
        let mut col = 0usize;
        for (i, ch) in src.char_indices() {
            if i >= byte_index { break; }
            if ch == '\n' { line += 1; col = 0; } else { col += 1; }
        }
        if byte_index >= src.len() && !src.is_empty() {
            line = 1; col = 0;
            for ch in src.chars() {
                if ch == '\n' { line += 1; col = 0; } else { col += 1; }
            }
        }
        ScanError { mark: Marker { index: byte_index, line, col }, info: info.to_string() }
    }
}

#[derive(Clone)]
struct LineInfo {
    raw: String,
    content: String, // after indent, comment stripped, right-trimmed
    indent: usize,   // number of leading whitespace chars
    byte_start: usize, // byte offset in src of raw line start
    significant: bool,
}

fn strip_comment(s: &str) -> &str {
    let mut in_s = false;
    let mut in_d = false;
    let mut prev: Option<char> = None;
    let mut chars = s.char_indices().peekable();
    while let Some((i, ch)) = chars.next() {
        if in_d {
            if ch == '\\' { let _ = chars.next(); prev = Some(ch); continue; }
            if ch == '"' { in_d = false; }
        } else if in_s {
            if ch == '\'' {
                if let Some((_, '\'')) = chars.peek() { let _ = chars.next(); } else { in_s = false; }
            }
        } else {
            match ch {
                '"' => in_d = true,
                '\'' => in_s = true,
                '#' => {
                    if i == 0 || matches!(prev, Some(' ') | Some('\t')) {
                        return &s[..i];
                    }
                }
                _ => {}
            }
        }
        prev = Some(ch);
    }
    s
}

fn make_line(raw: &str, byte_start: usize) -> LineInfo {
    let no_comment = strip_comment(raw);
    let trimmed_right = no_comment.trim_end();
    let mut indent = 0usize;
    for ch in trimmed_right.chars() {
        if ch == ' ' || ch == '\t' { indent += 1; } else { break; }
    }
    // content starts after indent bytes: indent chars are ascii spaces/tabs, byte == count
    let content = if indent <= trimmed_right.len() { trimmed_right[indent..].to_string() } else { String::new() };
    let significant = !content.trim().is_empty();
    LineInfo { raw: raw.to_string(), content, indent, byte_start, significant }
