fn classify_plain(raw: &str) -> Yaml {
    let s = raw.trim();
    if s.is_empty() || s == "null" || s == "~" {
        return Yaml::Null;
    }
    if s == "true" { return Yaml::Bool(true); }
    if s == "false" { return Yaml::Bool(false); }
    if let Some(i) = parse_yaml_int(s) { return Yaml::Int(i); }
    if is_yaml_float(s) { return Yaml::Real(s.to_string()); }
    Yaml::Str(s.to_string())
}

fn parse_yaml_int(s: &str) -> Option<i64> {
    let mut t = s;
    let mut sign = 1i64;
    if let Some(rest) = t.strip_prefix('-') { sign = -1; t = rest; }
    else if let Some(rest) = t.strip_prefix('+') { t = rest; }
    if t.is_empty() { return None; }
    if let Some(hex) = t.strip_prefix("0x").or_else(|| t.strip_prefix("0X")) {
        if !hex.is_empty() && hex.chars().all(|c| c.is_ascii_hexdigit() || c == '_') {
            return i64::from_str_radix(&hex.replace('_', ""), 16).ok().map(|v| sign * v);
        }
        return None;
    }
    if let Some(oct) = t.strip_prefix("0o").or_else(|| t.strip_prefix("0O")) {
        if !oct.is_empty() && oct.chars().all(|c| ('0'..='7').contains(&c) || c == '_') {
            return i64::from_str_radix(&oct.replace('_', ""), 8).ok().map(|v| sign * v);
        }
        return None;
    }
    if t.chars().all(|c| c.is_ascii_digit() || c == '_') && t.chars().any(|c| c.is_ascii_digit()) {
        // Reject underscores at ends? Approximation is sufficient for typing.
        return t.replace('_', "").parse::<i64>().ok().map(|v| sign * v);
    }
    None
}

fn is_yaml_float(s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    if lower == ".inf" || lower == "+.inf" || lower == "-.inf" || lower == ".nan" {
