        idx += 1;
    }
    None
}

fn is_flow_incomplete(s: &str) -> bool {
    let mut in_s = false;
    let mut in_d = false;
    let mut depth = 0i32;
    let mut chars = s.chars().peekable();
    while let Some(ch) = chars.next() {
        if in_d {
            if ch == '\\' { let _ = chars.next(); continue; }
            if ch == '"' { in_d = false; }
        } else if in_s {
            if ch == '\'' {
                if chars.peek() == Some(&'\'') { let _ = chars.next(); } else { in_s = false; }
            }
        } else {
            match ch {
                '"' => in_d = true,
                '\'' => in_s = true,
                '{' | '[' => depth += 1,
                '}' | ']' => depth -= 1,
                _ => {}
            }
        }
    }
    in_s || in_d || depth > 0
