            match self.bump() {
                None => return Err(self.err(start, "while scanning a quoted scalar, found unexpected end of stream")),
                Some('"') => break,
                Some('\\') => {
                    match self.bump() {
                        None => return Err(self.err(start, "while scanning a quoted scalar, found unexpected end of stream")),
                        Some('n') => out.push('\n'),
                        Some('t') => out.push('\t'),
                        Some('r') => out.push('\r'),
                        Some('0') => out.push('\0'),
                        Some('\\') => out.push('\\'),
                        Some('"') => out.push('"'),
                        Some('\'') => out.push('\''),
                        Some('/') => out.push('/'),
                        Some('b') => out.push('\u{0008}'),
                        Some('f') => out.push('\u{000c}'),
