                        }
                        Some('u') => {
                            let h = self.take_hex(4);
                            if let Some(v) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) { out.push(v); }
                        }
                        Some('U') => {
                            let h = self.take_hex(8);
                            if let Some(v) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) { out.push(v); }
                        }
