pub fn find(name: &str) -> Option<&'static Builtin> {
    THEMES.iter().find(|t| t.name == name)
}

fn s(v: &str) -> Yaml { Yaml::Str(v.to_string()) }

pub fn to_yaml(t: &Builtin) -> Yaml {
    let mut top: Vec<(Yaml, Yaml)> = Vec::new();
    insert_hash(&mut top, s("colors"), Yaml::Hash(Vec::new()));
    // bar_colors
    let mut bar: Vec<(Yaml, Yaml)> = Vec::new();
    if let Some(v) = t.separator { insert_hash(&mut bar, s("separator"), s(v)); }
    if let Some(v) = t.background { insert_hash(&mut bar, s("background"), s(v)); }
    if let Some(v) = t.statusline { insert_hash(&mut bar, s("statusline"), s(v)); }
    let ws_names = ["focused_workspace", "active_workspace", "inactive_workspace", "urgent_workspace"];
    for (i, ws) in t.workspaces.iter().enumerate() {
        if let Some((b, bg, tx)) = ws {
            let mut h = Vec::new();
            insert_hash(&mut h, s("border"), s(b));
            insert_hash(&mut h, s("background"), s(bg));
            insert_hash(&mut h, s("text"), s(tx));
            insert_hash(&mut bar, s(ws_names[i]), Yaml::Hash(h));
        }
    }
    insert_hash(&mut top, s("bar_colors"), Yaml::Hash(bar));
    // window_colors
    let mut wins: Vec<(Yaml, Yaml)> = Vec::new();
    let win_names = ["focused", "focused_inactive", "unfocused", "urgent"];
    for (i, wv) in t.windows.iter().enumerate() {
        if let Some((b, bg, tx, ind)) = wv {
            let mut h = Vec::new();
            insert_hash(&mut h, s("border"), s(b));
            insert_hash(&mut h, s("background"), s(bg));
            insert_hash(&mut h, s("text"), s(tx));
            insert_hash(&mut h, s("indicator"), s(ind));
            insert_hash(&mut wins, s(win_names[i]), Yaml::Hash(h));
        }
    }
    insert_hash(&mut top, s("window_colors"), Yaml::Hash(wins));
    Yaml::Hash(top)
}
RS_EOF
"}

{"command":"cat > src/writer.rs <<'RS_EOF'
use crate::yaml::{lookup, Yaml};
use std::fs::File;
use std::io::{self, BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

const BAR_PROPS: [&str; 7] = [
    "separator",
    "background",
    "statusline",
    "focused_workspace",
    "active_workspace",
    "inactive_workspace",
    "urgent_workspace",
];
const WINDOWS: [(&str, &str); 4] = [
    ("client.focused", "focused"),
    ("client.focused_inactive", "focused_inactive"),
    ("client.unfocused", "unfocused"),
    ("client.urgent", "urgent"),
];

fn resolve(theme: &Yaml, node: Option<&Yaml>) -> Option<String> {
    let name = node.and_then(|v| v.as_str())?;
    if let Some(v) = lookup(lookup(Some(theme), "colors"), name).and_then(|v| v.as_str()) {
        Some(v.to_string())
    } else {
        Some(name.to_string())
    }
}
fn resolve_in(theme: &Yaml, parent: Option<&Yaml>, key: &str) -> Option<String> {
    resolve(theme, lookup(parent, key))
}

pub struct Writer {
    theme: Yaml,
    reader: BufReader<File>,
    output: Box<dyn Write>,
    in_bar: bool,
    in_colors: bool,
    seen_bar: [bool; 7],
    seen_window: [bool; 4],
}

impl Writer {
    pub fn new(config_path: &Path, theme: Yaml, output_path: Option<PathBuf>) -> Self {
        let file = File::open(config_path).unwrap();
        let reader = BufReader::new(file);
        let output: Box<dyn Write> = if let Some(p) = output_path {
            Box::new(File::create(p).unwrap())
        } else {
            Box::new(io::stdout())
        };
        Writer { theme, reader, output, in_bar: false, in_colors: false, seen_bar: [false; 7], seen_window: [false; 4] }
    }
    fn write_str(&mut self, s: &str) {
        write!(self.output, "{}", s).unwrap();
        self.output.flush().unwrap();
    }
    fn write_line(&mut self, s: &str) {
        writeln!(self.output, "{}", s).unwrap();
        self.output.flush().unwrap();
    }
    fn bar_colors_node(&self) -> Option<&Yaml> {
        lookup(Some(&self.theme), "bar_colors")
    }
    fn window_colors_node(&self) -> Option<&Yaml> {
        lookup(Some(&self.theme), "window_colors")
    }
    fn bar_single(&self, prop: &str) -> Option<String> {
        resolve_in(&self.theme, self.bar_colors_node(), prop)
    }
    fn workspace_entry(&self, prop: &str) -> Option<Yaml> {
        let e = lookup(self.bar_colors_node(), prop)?;
        if e.as_hash().is_some() { Some(e.clone()) } else { None }
    }
    fn window_entry(&self, name: &str) -> Option<Yaml> {
        let e = lookup(self.window_colors_node(), name)?;
        if e.as_hash().is_some() { Some(e.clone()) } else { None }
    }
    fn write_bar_entry_insert(&mut self, indent: &str, prop_idx: usize) {
        let prop = BAR_PROPS[prop_idx];
        if prop_idx < 3 {
            if let Some(c) = self.bar_single(prop) {
                self.write_line(&format!("{}{} {}", indent, prop, c));
            }
        } else {
            if let Some(entry) = self.workspace_entry(prop) {
                let border = resolve_in(&self.theme, Some(&entry), "border");
                let background = resolve_in(&self.theme, Some(&entry), "background");
                let text = resolve_in(&self.theme, Some(&entry), "text");
                let indicator = resolve_in(&self.theme, Some(&entry), "indicator");
                if let (Some(b), Some(bg), Some(tx)) = (border, background, text) {
                    self.write_str(&format!("{}{} ", indent, prop));
                    self.write_str(&format!("{} ", b));
                    self.write_str(&format!("{} ", bg));
                    self.write_str(&format!("{} ", tx));
                    if let Some(ind) = indicator {
                        self.write_str(&format!(" {}", ind));
                    }
                    self.write_str("\n");
                }
            }
        }
    }
    fn write_new_bar_colors(&mut self) {
        let _ = lookup(Some(&self.theme), "bar_colors").and_then(|v| v.as_hash()).unwrap();
        self.write_line("  colors {");
        for i in 0..BAR_PROPS.len() {
            self.write_bar_entry_insert("    ", i);
        }
        self.write_line("  }");
    }
    fn write_missing_bar_colors(&mut self, closing_indent: &str) {
        let _ = lookup(Some(&self.theme), "bar_colors").and_then(|v| v.as_hash()).unwrap();
        let indent = format!("{}{}", closing_indent, closing_indent);
        for i in 0..BAR_PROPS.len() {
            if !self.seen_bar[i] {
                self.write_bar_entry_insert(&indent, i);
            }
        }
    }
    fn write_workspace_replaced(&mut self, indent: &str, prop: &str, entry: &Yaml, parts: &[String]) {
        let border = resolve_in(&self.theme, Some(entry), "border");
        let background = resolve_in(&self.theme, Some(entry), "background");
        let text = resolve_in(&self.theme, Some(entry), "text");
        let indicator = resolve_in(&self.theme, Some(entry), "indicator");
        self.write_str(&format!("{}{} ", indent, prop));
        if let Some(v) = border { self.write_str(&format!("{} ", v)); } else { self.write_str(&format!("{} ", parts[1])); }
        if let Some(v) = background { self.write_str(&format!("{} ", v)); } else { self.write_str(&format!("{} ", parts[2])); }
        if let Some(v) = text { self.write_str(&format!("{}", v)); } else { self.write_str(&format!("{}", parts[3])); }
        if let Some(v) = indicator {
            self.write_str(&format!(" {}", v));
        } else if parts.len() > 3 {
            self.write_str(&format!(" {}", parts[3]));
        }
        self.write_str("\n");
    }
    fn write_client_replaced(&mut self, indent: &str, client_key: &str, entry: &Yaml, parts: &[String]) {
        let border = resolve_in(&self.theme, Some(entry), "border");
        let background = resolve_in(&self.theme, Some(entry), "background");
        let text = resolve_in(&self.theme, Some(entry), "text");
        let indicator = resolve_in(&self.theme, Some(entry), "indicator");
        self.write_str(&format!("{}{} ", indent, client_key));
        if let Some(v) = border { self.write_str(&format!("{} ", v)); } else { self.write_str(&format!("{} ", parts[1])); }
        if let Some(v) = background { self.write_str(&format!("{} ", v)); } else { self.write_str(&format!("{} ", parts[2])); }
        if text.is_none() && parts.len() <= 3 {
            self.write_str("\n");
            return;
        }
        if let Some(v) = text { self.write_str(&format!("{} ", v)); } else { self.write_str(&format!("{} ", parts[3])); }
        let ind_val = if let Some(v) = indicator { v } else if parts.len() > 4 { parts[4].clone() } else { String::new() };
        self.write_line(&ind_val);
    }
    fn write_missing_window_colors(&mut self) {
        let _ = lookup(Some(&self.theme), "window_colors").and_then(|v| v.as_hash()).unwrap();
        for (idx, (client_key, win_name)) in WINDOWS.iter().enumerate() {
            if self.seen_window[idx] { continue; }
            let entry = match self.window_entry(win_name) { Some(e) => e, None => continue };
            let border = resolve_in(&self.theme, Some(&entry), "border").unwrap_or_else(|| "#000000".to_string());
            let background = resolve_in(&self.theme, Some(&entry), "background").unwrap_or_else(|| "#000000".to_string());
            let text = resolve_in(&self.theme, Some(&entry), "text").unwrap_or_else(|| "#000000".to_string());
            let mut line = format!("{} {} {} {}", client_key, border, background, text);
            if let Some(ind) = resolve_in(&self.theme, Some(&entry), "indicator") {
                line.push_str(&format!(" {}", ind));
            }
            self.write_line(&line);
        }
    }
    pub fn write(&mut self) {
        let mut lines_iter = (&mut self.reader).lines();
        loop {
            let line_opt = lines_iter.next();
            let line = match line_opt {
                Some(r) => r.unwrap(),
                None => break,
            };
            let trimmed = line.trim().to_string();
            let parts: Vec<String> = trimmed.split(' ').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect();
            let first = parts.get(0).cloned();
            let indent_len = line.len() - line.trim_start().len();
            let indent = line[..indent_len].to_string();
            if self.in_colors {
                if first.as_deref() == Some("}") {
                    let closing_indent = indent.clone();
                    self.write_missing_bar_colors(&closing_indent);
                    self.in_colors = false;
                    self.write_line(&line);
                    continue;
                }
                if trimmed.is_empty() || trimmed.starts_with('#') {
                    self.write_line(&line);
                    continue;
                }
                if let Some(prop) = first.as_deref() {
                    if let Some(prop_idx) = BAR_PROPS.iter().position(|p| *p == prop) {
                        self.seen_bar[prop_idx] = true;
                        if prop_idx < 3 {
                            if let Some(c) = self.bar_single(prop) {
                                self.write_line(&format!("{}{} {}", indent, prop, c));
                            } else {
                                self.write_line(&line);
                            }
                        } else {
                            if let Some(entry) = self.workspace_entry(prop) {
                                self.write_workspace_replaced(&indent, prop, &entry, &parts);
                            } else {
                                self.write_line(&line);
                            }
                        }
                        continue;
                    }
                }
                // unknown lines inside colors are dropped
                continue;
            }
            if self.in_bar {
                if first.as_deref() == Some("colors") {
                    self.in_colors = true;
                    self.seen_bar = [false; 7];
                    self.write_line(&line);
                    continue;
                }
                if first.as_deref() == Some("}") {
                    self.write_new_bar_colors();
                    self.in_bar = false;
                    self.write_line(&line);
                    continue;
                }
            } else {
                if first.as_deref() == Some("bar") {
                    self.in_bar = true;
                    self.write_line(&line);
                    continue;
                }
            }
            // client handling outside colors
            let mut handled_client = false;
            if let Some(f) = first.as_deref() {
                for (idx, (client_key, win_name)) in WINDOWS.iter().enumerate() {
                    if f == *client_key {
                        handled_client = true;
                        if let Some(entry) = self.window_entry(win_name) {
                            self.seen_window[idx] = true;
                            self.write_client_replaced(&indent, client_key, &entry, &parts);
                        } else {
                            self.write_line(&line);
                        }
                        break;
                    }
                }
            }
            if handled_client { continue; }
            self.write_line(&line);
        }
        self.write_missing_window_colors();
    }
}
RS_EOF
"}

