use crate::color;
use std::collections::{HashMap, HashSet};
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

#[derive(Default, Clone)]
struct WorkspaceRaw {
    present: bool,
    border: Option<String>,
    background: Option<String>,
    text: Option<String>,
}
#[derive(Default, Clone)]
struct WindowRaw {
    present: bool,
    border: Option<String>,
    background: Option<String>,
    text: Option<String>,
    indicator: Option<String>,
}

fn yaml_quote(s: &str) -> String {
    if needs_quote(s) {
        let mut out = String::from("\"");
        for ch in s.chars() {
            match ch {
                '"' => out.push_str("\\\""),
                '\\' => out.push_str("\\\\"),
                '\n' => out.push_str("\\n"),
                '\r' => out.push_str("\\r"),
                '\t' => out.push_str("\\t"),
                '\0' => out.push_str("\\0"),
                c if (c as u32) < 0x20 => out.push_str(&format!("\\x{:02X}", c as u32)),
                c => out.push(c),
            }
        }
        out.push('"');
        out
    } else {
        s.to_string()
    }
}
fn needs_quote(s: &str) -> bool {
    if s.is_empty() { return true; }
    // serde_yaml/libyaml style approximation
    let first = s.chars().next().unwrap();
    if matches!(first, '#' | '{' | '}' | '[' | ']' | ',' | '&' | '*' | '!' | '|' | '>' | '\'' | '"' | '%' | '@' | '`') {
        return true;
    }
    if s.starts_with("- ") || s.starts_with(": ") || s.starts_with("? ") || s == "-" || s == ":" || s == "?" {
        return true;
    }
    if s != s.trim() { return true; }
    if s.contains(": ") || s.contains(" #") || s.contains('\n') || s.contains('\r') || s.contains('\t') {
        return true;
    }
    if s.chars().any(|c| (c as u32) < 0x20) { return true; }
    let lower = s.to_ascii_lowercase();
    if matches!(lower.as_str(), "true" | "false" | "null" | "~" | ".inf" | "-.inf" | "+.inf" | ".nan") {
        return true;
    }
    // numeric-like checks
    if s.parse::<i64>().is_ok() || s.parse::<u64>().is_ok() {
        return true;
    }
    // Hex int in YAML 1.1 etc
    if (s.starts_with("0x") || s.starts_with("0X")) && s[2..].chars().all(|c| c.is_ascii_hexdigit()) {
        return true;
