        if in_colors {
            match first {
                Some("}") => { in_colors = false; }
                Some("separator") => { separator = Some(parts[1].to_uppercase()); }
                Some("background") => { background = Some(parts[1].to_uppercase()); }
                Some("statusline") => { statusline = Some(parts[1].to_uppercase()); }
                Some("focused_workspace") => update_ws(&mut focused_ws, &parts),
                Some("inactive_workspace") => update_ws(&mut inactive_ws, &parts),
                Some("urgent_workspace") => update_ws(&mut urgent_ws, &parts),
                _ => {}
            }
            continue;
        }
        if in_bar {
            match first {
                Some("colors") => in_colors = true,
                Some("}") => in_bar = false,
                _ => {}
            }
            continue;
        }
        match first {
            Some("bar") => in_bar = true,
            Some("client.focused") => update_win(&mut focused, &parts),
            Some("client.focused_inactive") => update_win(&mut focused_inactive, &parts),
            Some("client.unfocused") => update_win(&mut unfocused, &parts),
            Some("client.urgent") => update_win(&mut urgent, &parts),
            _ => {}
        }
    }

    let mut reg = ColorRegistry::new();
    let sep_name = reg.add_opt(&separator);
    let bg_name = reg.add_opt(&background);
    let status_name = reg.add_opt(&statusline);
    let fws_names = reg_ws(&mut reg, &focused_ws);
    let _iws_names = reg_ws(&mut reg, &inactive_ws);
    let uws_names = reg_ws(&mut reg, &urgent_ws);
    let focused_names = reg_win(&mut reg, &focused);
    let focused_inactive_names = reg_win(&mut reg, &focused_inactive);
    let unfocused_names = reg_win(&mut reg, &unfocused);
    let urgent_names = reg_win(&mut reg, &urgent);

    let mut out = String::new();
    out.push_str("---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\n");
    if reg.order.is_empty() {
        out.push_str("colors: {}\n");
    } else {
        out.push_str("colors:\n");
        for (name, hex) in &reg.order {
            out.push_str(&format!("  {}: {}\n", name, yaml_quote(hex)));
        }
    }
    let any_window = focused.present || focused_inactive.present || unfocused.present || urgent.present;
    if !any_window {
        out.push_str("window_colors: {}\n");
    } else {
        out.push_str("window_colors:\n");
        if focused.present { write_win(&mut out, "focused", &focused_names); }
        if focused_inactive.present { write_win(&mut out, "focused_inactive", &focused_inactive_names); }
        if unfocused.present { write_win(&mut out, "unfocused", &unfocused_names); }
        if urgent.present { write_win(&mut out, "urgent", &urgent_names); }
    }
    let any_bar = bg_name.is_some() || status_name.is_some() || sep_name.is_some() || focused_ws.present || urgent_ws.present;
    if !any_bar {
        out.push_str("bar_colors: {}\n");
    } else {
        out.push_str("bar_colors:\n");
        if let Some(n) = bg_name { out.push_str(&format!("  background: {}\n", n)); }
        if let Some(n) = status_name { out.push_str(&format!("  statusline: {}\n", n)); }
        if let Some(n) = sep_name { out.push_str(&format!("  separator: {}\n", n)); }
        if focused_ws.present { write_ws(&mut out, "focused_workspace", &fws_names); }
        if urgent_ws.present { write_ws(&mut out, "urgent_workspace", &uws_names); }
    }
    out
}

fn update_ws(ws: &mut WorkspaceRaw, parts: &[String]) {
    ws.border = Some(parts[1].to_uppercase());
    ws.background = Some(parts[2].to_uppercase());
    if parts.len() > 3 {
        ws.text = Some(parts[3].to_uppercase());
    }
    ws.present = true;
}
fn update_win(w: &mut WindowRaw, parts: &[String]) {
    w.border = Some(parts[1].to_uppercase());
    w.background = Some(parts[2].to_uppercase());
    w.text = Some(parts[3].to_uppercase());
    if parts.len() > 4 {
        w.indicator = Some(parts[4].to_uppercase());
    }
    w.present = true;
}
fn reg_ws(reg: &mut ColorRegistry, ws: &WorkspaceRaw) -> (Option<String>, Option<String>, Option<String>) {
    (reg.add_opt(&ws.border), reg.add_opt(&ws.background), reg.add_opt(&ws.text))
}
fn reg_win(reg: &mut ColorRegistry, w: &WindowRaw) -> (Option<String>, Option<String>, Option<String>, Option<String>) {
    (reg.add_opt(&w.border), reg.add_opt(&w.background), reg.add_opt(&w.text), reg.add_opt(&w.indicator))
}
fn write_ws(out: &mut String, name: &str, names: &(Option<String>, Option<String>, Option<String>)) {
    out.push_str(&format!("  {}:\n", name));
    if let Some(n) = &names.0 { out.push_str(&format!("    border: {}\n", n)); }
    if let Some(n) = &names.1 { out.push_str(&format!("    background: {}\n", n)); }
    if let Some(n) = &names.2 { out.push_str(&format!("    text: {}\n", n)); }
}
fn write_win(out: &mut String, name: &str, names: &(Option<String>, Option<String>, Option<String>, Option<String>)) {
    out.push_str(&format!("  {}:\n", name));
    if let Some(n) = &names.0 { out.push_str(&format!("    border: {}\n", n)); }
    if let Some(n) = &names.1 { out.push_str(&format!("    background: {}\n", n)); }
    if let Some(n) = &names.2 { out.push_str(&format!("    text: {}\n", n)); }
    if let Some(n) = &names.3 { out.push_str(&format!("    indicator: {}\n", n)); }
}
RS_EOF
"}

