    if used.is_empty() {
        format!("{} [FLAGS] [OPTIONS] [theme]", bin)
    } else {
        let parts: Vec<String> = used.iter().map(|l| format_arg_for_usage(l)).collect();
        format!("{} {}", bin, parts.join(" "))
    }
}
fn error_unknown(bin: &str, arg_display: &str, suggestion: Option<String>, used_in: &BTreeSet<String>) -> ! {
    let mut used = used_in.clone();
    if let Some(s) = &suggestion { used.insert(s.clone()); }
    let usage = smart_usage(bin, &used);
    eprint!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n", arg_display);
    if let Some(s) = suggestion {
        eprint!("\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?\n", s);
    }
    eprint!("\nUSAGE:\n    {}\n\nFor more information try --help\n", usage);
    let _ = io::stderr().flush();
    process::exit(1);
}
fn error_validation(bin: &str, msg: String, used: &BTreeSet<String>) -> ! {
    let usage = smart_usage(bin, used);
    eprint!("error: {}\n\nUSAGE:\n    {}\n\nFor more information try --help\n", msg, usage);
    let _ = io::stderr().flush();
    process::exit(1);
}

// Jaro-Winkler, following the commonly used strsim algorithm.
fn jaro(a: &str, b: &str) -> f64 {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    if a_chars.is_empty() && b_chars.is_empty() { return 1.0; }
    if a_chars.is_empty() || b_chars.is_empty() { return 0.0; }
    if a_chars == b_chars { return 1.0; }
    let max_dist = (a_chars.len().max(b_chars.len()) / 2).saturating_sub(1);
    let mut a_match = vec![false; a_chars.len()];
    let mut b_match = vec![false; b_chars.len()];
    let mut matches = 0usize;
    for i in 0..a_chars.len() {
        let start = if i > max_dist { i - max_dist } else { 0 };
        let end = (i + max_dist + 1).min(b_chars.len());
        for j in start..end {
            if !b_match[j] && a_chars[i] == b_chars[j] {
                a_match[i] = true;
                b_match[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 { return 0.0; }
    let mut b_iter = 0usize;
    let mut transpositions = 0usize;
    for i in 0..a_chars.len() {
        if a_match[i] {
            while !b_match[b_iter] { b_iter += 1; }
            if a_chars[i] != b_chars[b_iter] { transpositions += 1; }
            b_iter += 1;
        }
    }
    let m = matches as f64;
    (m / a_chars.len() as f64 + m / b_chars.len() as f64 + (m - (transpositions as f64 / 2.0)) / m) / 3.0
}
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j > 0.7 {
        let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).take(4).count();
        j + (prefix as f64 * 0.1 * (1.0 - j))
    } else {
        j
    }
}
fn did_you_mean(name: &str) -> Option<String> {
    let candidates = ["help", "list-all", "reload", "save", "version", "config", "output", "to-theme"];
    let mut best: Option<String> = None;
    let mut best_conf = 0.8f64;
    for cand in candidates {
        let conf = jaro_winkler(name, cand);
        if conf > best_conf {
            best_conf = conf;
            best = Some(cand.to_string());
        }
    }
    best
}

fn can_be_value(s: &str) -> bool {
    s == "-" || s.is_empty() || !s.starts_with('-')
}

fn parse_matches(bin: &str, args: Vec<String>) -> Matches {
    let mut used: BTreeSet<String> = BTreeSet::new();
    let mut occurrences: HashMap<String, usize> = HashMap::new();
    let mut option_values: HashMap<String, Vec<Option<String>>> = HashMap::new();
    let mut flags_present: HashMap<String, bool> = HashMap::new();
    let mut theme: Option<String> = None;
    let mut to_theme_present = false;
    let mut after_ddash = false;
    let mut i = 0usize;
    let mut record_flag = |used: &mut BTreeSet<String>, occurrences: &mut HashMap<String, usize>, flags_present: &mut HashMap<String, bool>, long: &str| {
        used.insert(long.to_string());
        *occurrences.entry(long.to_string()).or_insert(0) += 1;
        flags_present.insert(long.to_string(), true);
    };
    while i < args.len() {
        let arg = args[i].clone();
        if after_ddash {
            if theme.is_some() {
                error_unknown(bin, &arg, None, &used);
            }
            theme = Some(arg);
            i += 1;
            continue;
        }
        if arg == "--" {
            after_ddash = true;
            i += 1;
            continue;
        }
        if arg.starts_with("--") && arg.len() > 2 {
            // Long argument: strip all leading '-'
            let stripped = arg.trim_start_matches('-');
            let (name, attached) = if let Some(eq) = stripped.find('=') {
                (&stripped[..eq], Some(stripped[eq + 1..].to_string()))
            } else {
                (stripped, None)
            };
            let name_string = name.to_string();
            match name_string.as_str() {
                "help" => print_help(bin),
                "version" => print_version(),
                "list-all" | "reload" | "save" => {
                    record_flag(&mut used, &mut occurrences, &mut flags_present, &name_string);
                    i += 1;
                    continue;
                }
                "config" | "output" | "to-theme" => {
                    let is_to_theme = name_string == "to-theme";
                    used.insert(name_string.clone());
                    *occurrences.entry(name_string.clone()).or_insert(0) += 1;
                    if is_to_theme { to_theme_present = true; }
                    let value: Option<String>;
                    if let Some(att) = attached {
                        value = Some(att.trim_start_matches('=').to_string());
                        i += 1;
                    } else if i + 1 < args.len() && can_be_value(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        // No value consumed
                        if is_to_theme {
                            value = Some(String::new());
                        } else {
                            value = None;
                        }
                        i += 1;
                    }
                    option_values.entry(name_string.clone()).or_default().push(value);
                    continue;
                }
                _ => {
                    let suggestion = did_you_mean(&name_string);
                    let display = format!("--{}", name_string);
                    error_unknown(bin, &display, suggestion, &used);
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // Short cluster
            let cluster = &arg[1..];
            let mut char_indices: Vec<(usize, char)> = cluster.char_indices().collect();
            char_indices.push((cluster.len(), '\0'));
            let mut consumed_next_arg = false;
            let mut advance = 1usize;
            let mut j = 0usize;
            while j + 1 < char_indices.len() {
                let (byte_idx, ch) = char_indices[j];
                let next_byte_idx = char_indices[j + 1].0;
                match ch {
                    'h' => print_help(bin),
                    'V' => print_version(),
                    'l' | 'r' | 's' => {
                        let long = match ch { 'l' => "list-all", 'r' => "reload", _ => "save" };
                        record_flag(&mut used, &mut occurrences, &mut flags_present, long);
                        j += 1;
                    }
                    'c' | 'o' | 't' => {
                        let long = match ch { 'c' => "config", 'o' => "output", _ => "to-theme" };
                        let is_to_theme = ch == 't';
                        used.insert(long.to_string());
                        *occurrences.entry(long.to_string()).or_insert(0) += 1;
                        if is_to_theme { to_theme_present = true; }
                        let rest = &cluster[next_byte_idx..];
                        let value: Option<String>;
                        if !rest.is_empty() {
                            if let Some(stripped_eq) = rest.strip_prefix('=') {
                                // one '=' is the separator; additionally clap strips further '=' from the value
                                value = Some(stripped_eq.trim_start_matches('=').to_string());
                            } else {
                                value = Some(rest.to_string());
                            }
                        } else if i + 1 < args.len() && can_be_value(&args[i + 1]) {
                            value = Some(args[i + 1].clone());
                            consumed_next_arg = true;
                            advance = 2;
                        } else {
                            if is_to_theme { value = Some(String::new()); } else { value = None; }
                        }
                        option_values.entry(long.to_string()).or_default().push(value);
                        break; // rest of cluster is the value
                    }
                    _ => {
                        let display = format!("-{}", ch);
                        error_unknown(bin, &display, None, &used);
                    }
                }
                let _ = byte_idx;
            }
            let _ = consumed_next_arg;
            i += advance;
            continue;
        } else {
            // Positional
            if theme.is_some() {
                error_unknown(bin, &arg, None, &used);
            }
            theme = Some(arg);
            i += 1;
            continue;
        }
    }
    // Validation (only if no help/version/unknown occurred)
    let mut used_val = used.clone();
    used_val.insert("to-theme".to_string());
    // Iterate in alphabetical order for deterministic diagnostics when there is a single error.
    for long in ["config", "list-all", "output", "reload", "save", "to-theme"] {
        let occ = occurrences.get(long).copied().unwrap_or(0);
        if occ > 1 {
            let arg_display = format_arg_for_usage(long);
            error_validation(bin, format!("The argument '{}' was provided more than once, but cannot be used multiple times", arg_display), &used_val);
        }
        if long == "config" || long == "output" {
            if let Some(vals) = option_values.get(long) {
                if vals.iter().any(|v| v.is_none()) {
                    let arg_display = format_arg_for_usage(long);
                    error_validation(bin, format!("The argument '{}' requires a value but none was supplied", arg_display), &used_val);
                }
            }
        }
    }
    let get_opt = |key: &str| -> Option<String> {
        option_values.get(key).and_then(|v| v.get(0)).cloned().flatten()
    };
    Matches {
        list_all: flags_present.get("list-all").copied().unwrap_or(false),
        reload: flags_present.get("reload").copied().unwrap_or(false),
        save: flags_present.get("save").copied().unwrap_or(false),
        config: get_opt("config"),
        output: get_opt("output"),
        to_theme_present,
        to_theme: option_values.get("to-theme").and_then(|v| v.get(0)).cloned().flatten().unwrap_or_default(),
        theme,
    }
}

fn create_temp_dir() -> PathBuf {
    let duration = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
    let num = duration.as_secs() + duration.subsec_millis() as u64;
    let path = env::temp_dir().join("i3-style").join(num.to_string());
    fs::create_dir_all(&path).expect("Could not create temporary directory");
    path
}

fn main() {
    let bin = bin_name();
    let argv: Vec<String> = env::args_os().skip(1).map(|s| s.to_string_lossy().to_string()).collect();
    let _ = HELP_FLAGS_OPTIONS;
    let matches = parse_matches(&bin, argv);
    if matches.list_all {
        print!("\nAvailable themes:\n\n");
        for t in builtin::THEMES {
            println!("  {:<18} - {}", t.name, t.description);
        }
        let _ = io::stdout().flush();
        return;
    }
    if matches.theme.is_none() && !matches.to_theme_present {
        println!("USAGE:\n    {} [FLAGS] [OPTIONS] [theme]\n\nSelect a theme as the first argument. Use `--list-all` to see the themes.", bin);
        process::exit(1);
    }
    let config_path: String = if matches.to_theme_present && !matches.to_theme.is_empty() {
        matches.to_theme.clone()
    } else if let Some(c) = &matches.config {
        c.clone()
    } else {
        let home = env::var("HOME").unwrap();
        let first = format!("{}/.i3/config", home);
        let second = format!("{}/.config/i3/config", home);
        if Path::new(&first).exists() {
            first
        } else if Path::new(&second).exists() {
            second
        } else {
            eprintln!("Could not find i3 config");
            process::exit(1);
        }
    };
    // Validate
    match Command::new("i3").arg("-C").arg("-c").arg(&config_path).output() {
        Err(e) => {
            eprintln!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", config_path, e);
            process::exit(1);
        }
        Ok(out) => {
            if !out.status.success() {
                eprintln!("Could not validate config.\nUse `i3 -C -c {}` to see validation errors.", config_path);
                process::exit(1);
            }
        }
    }
    if matches.to_theme_present {
        let generated = theme::theme_from_config(Path::new(&config_path));
        print!("{}", generated);
        let _ = io::stdout().flush();
        return;
    }
    let theme_name = matches.theme.clone().unwrap();
    let theme_yaml: yaml::Yaml = if let Some(b) = builtin::find(&theme_name) {
        builtin::to_yaml(b)
    } else {
        let content = match fs::read_to_string(&theme_name) {
            Err(e) => {
                eprintln!("Could not open theme: {} - {}\n Use `i3-style --list-all` to see the available themes.", theme_name, e);
                process::exit(1);
            }
            Ok(v) => v,
        };
        let docs = yaml::load_from_str(&content).unwrap_or_else(|e| panic!("Could not parse yaml for theme: {:?}", e));
        docs[0].clone()
    };
    let output_path: Option<String> = if let Some(o) = &matches.output {
        Some(o.clone())
    } else if matches.save {
        Some(config_path.clone())
    } else {
        None
    };
    let mut temp_dir: Option<PathBuf> = None;
    let writer_output: Option<PathBuf> = if output_path.is_some() {
        let td = create_temp_dir();
        let p = td.join("config-output");
        temp_dir = Some(td);
        Some(p)
    } else {
        None
    };
    {
        let mut w = writer::Writer::new(Path::new(&config_path), theme_yaml, writer_output);
        w.write();
    }
    if let Some(out_path) = &output_path {
        let td = temp_dir.as_ref().unwrap();
        let backup = td.join("config-input");
        eprintln!("saving config at {} to {}", config_path, backup.display());
        fs::copy(&config_path, &backup).unwrap();
        fs::copy(td.join("config-output"), out_path).unwrap();
    }
    if matches.reload {
        match Command::new("i3-msg").arg("reload").output() {
            Err(e) => {
                eprintln!("Could not reload config with i3-msg: {}", e);
                process::exit(1);
            }
            Ok(_) => {}
        }
    }
}
