    let mut occurrences: HashMap<String, usize> = HashMap::new();
    let mut option_values: HashMap<String, Vec<Option<Vec<u8>>>> = HashMap::new();
    let mut flags_present: HashMap<String, bool> = HashMap::new();
    let mut theme: Option<Vec<u8>> = None;
    let mut to_theme_present = false;
    let mut after_ddash = false;
    let mut i = 0usize;
    macro_rules! record_flag {
        ($long:expr) => {{
            let long_s: &str = $long;
            used.insert(long_s.to_string());
            *occurrences.entry(long_s.to_string()).or_insert(0) += 1;
            flags_present.insert(long_s.to_string(), true);
        }};
    }
    while i < args.len() {
        let arg = args[i].clone();
        if after_ddash {
            if theme.is_some() {
                let disp = String::from_utf8_lossy(&arg).to_string();
                error_unknown(bin, &disp, None, &used);
            }
            theme = Some(arg);
            i += 1;
            continue;
        }
        if arg == b"--".to_vec() {
            after_ddash = true;
            i += 1;
            continue;
        }
        if arg.len() > 2 && arg[0] == b'-' && arg[1] == b'-' {
            let mut strip_idx = 0usize;
            while strip_idx < arg.len() && arg[strip_idx] == b'-' { strip_idx += 1; }
            let stripped = &arg[strip_idx..];
            let eq_pos = stripped.iter().position(|b| *b == b'=');
            let (name_bytes, attached_raw): (&[u8], Option<Vec<u8>>) = if let Some(eq) = eq_pos {
                (&stripped[..eq], Some(stripped[eq + 1..].to_vec()))
            } else {
                (stripped, None)
            };
            let name_string = std::str::from_utf8(name_bytes).expect("unexpected invalid UTF-8 code point").to_string();
            match name_string.as_str() {
                "help" => print_help(bin),
                "version" => print_version(),
                "list-all" | "reload" | "save" => {
                    record_flag!(name_string.as_str());
                    i += 1;
                    continue;
                }
                "config" | "output" | "to-theme" => {
                    let is_to_theme = name_string == "to-theme";
                    used.insert(name_string.clone());
                    *occurrences.entry(name_string.clone()).or_insert(0) += 1;
                    if is_to_theme { to_theme_present = true; }
                    let value: Option<Vec<u8>>;
                    if let Some(att) = attached_raw {
                        let mut v = att.as_slice();
                        while !v.is_empty() && v[0] == b'=' { v = &v[1..]; }
                        value = Some(v.to_vec());
                        i += 1;
                    } else if i + 1 < args.len() && can_be_value(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        value = if is_to_theme { Some(Vec::new()) } else { None };
                        i += 1;
                    }
                    option_values.entry(name_string.clone()).or_default().push(value);
                    continue;
                }
                _ => {
                    let suggestion = did_you_mean(&name_string);
                    let display = format!("--{}", name_string);
                    error_unknown(bin, &display, suggestion, &used);
                }
            }
        } else if arg.len() > 1 && arg[0] == b'-' {
            let cluster_lossy = String::from_utf8_lossy(&arg[1..]).into_owned();
            let mut char_indices: Vec<(usize, char)> = cluster_lossy.char_indices().collect();
            char_indices.push((cluster_lossy.len(), '\0'));
            let mut advance = 1usize;
            let mut j = 0usize;
            while j + 1 < char_indices.len() {
                let (byte_idx, ch) = char_indices[j];
                let next_byte_idx = char_indices[j + 1].0;
                match ch {
                    'h' => print_help(bin),
                    'V' => print_version(),
                    'l' | 'r' | 's' => {
                        let long = match ch { 'l' => "list-all", 'r' => "reload", _ => "save" };
                        record_flag!(long);
                        j += 1;
                    }
                    'c' | 'o' | 't' => {
                        let long = match ch { 'c' => "config", 'o' => "output", _ => "to-theme" };
                        let is_to_theme = ch == 't';
                        used.insert(long.to_string());
                        *occurrences.entry(long.to_string()).or_insert(0) += 1;
                        if is_to_theme { to_theme_present = true; }
                        // Raw rest after this ASCII option char in the original token.
                        let presumed_raw_end_of_char = 1 + next_byte_idx;
                        let rest_raw: Vec<u8> = if presumed_raw_end_of_char <= arg.len()
                            && arg[1..presumed_raw_end_of_char] == *cluster_lossy[..next_byte_idx].as_bytes() {
                            arg[presumed_raw_end_of_char..].to_vec()
                        } else {
                            cluster_lossy[next_byte_idx..].as_bytes().to_vec()
                        };
                        let value: Option<Vec<u8>>;
                        if !rest_raw.is_empty() {
                            let mut v = rest_raw.as_slice();
                            if v[0] == b'=' {
                                while !v.is_empty() && v[0] == b'=' { v = &v[1..]; }
                            }
                            value = Some(v.to_vec());
                        } else if i + 1 < args.len() && can_be_value(&args[i + 1]) {
                            value = Some(args[i + 1].clone());
                            advance = 2;
                        } else {
                            value = if is_to_theme { Some(Vec::new()) } else { None };
                        }
                        option_values.entry(long.to_string()).or_default().push(value);
                        break;
                    }
                    _ => {
                        let display = format!("-{}", ch);
                        error_unknown(bin, &display, None, &used);
                    }
                }
                let _ = byte_idx;
            }
            i += advance;
            continue;
        } else {
            if theme.is_some() {
                let disp = String::from_utf8_lossy(&arg).to_string();
                error_unknown(bin, &disp, None, &used);
            }
            theme = Some(arg);
            i += 1;
            continue;
        }
    }
    let mut used_val = used.clone();
    used_val.insert("to-theme".to_string());
    for long in ["config", "list-all", "output", "reload", "save", "to-theme"] {
        let occ = occurrences.get(long).copied().unwrap_or(0);
        if occ > 1 {
            let arg_display = format_arg_for_usage(long);
            error_validation(bin, format!("The argument '{}' was provided more than once, but cannot be used multiple times", arg_display), &used_val);
        }
        if long == "config" || long == "output" {
            if let Some(vals) = option_values.get(long) {
                if vals.iter().any(|v| v.is_none()) {
                    let arg_display = format_arg_for_usage(long);
                    error_validation(bin, format!("The argument '{}' requires a value but none was supplied", arg_display), &used_val);
                }
            }
        }
    }
    let get_opt = |key: &str| -> Option<Vec<u8>> {
        option_values.get(key).and_then(|v| v.get(0)).cloned().flatten()
    };
    Matches {
        list_all: flags_present.get("list-all").copied().unwrap_or(false),
        reload: flags_present.get("reload").copied().unwrap_or(false),
        save: flags_present.get("save").copied().unwrap_or(false),
        config: get_opt("config"),
        output: get_opt("output"),
        to_theme_present,
        to_theme: option_values.get("to-theme").and_then(|v| v.get(0)).cloned().flatten().unwrap_or_default(),
        theme,
    }
}

fn utf8_expect(raw: &[u8]) -> String {
    std::str::from_utf8(raw).expect("unexpected invalid UTF-8 code point").to_string()
}

